-- (neutralizes Adonis anti-cheat interrogation on servers that run it)
--==============================================================
do
    local okB, errB = pcall(function()
        local src = game:HttpGet('https://raw.githubusercontent.com/Pixeluted/adoniscries/main/Source.lua')
        local fn = loadstring(src, 'acfix') or error("compile failed", 0)
        fn()
    end)
    print("[Untitled Cheat v2] anticheat bypass: " .. (okB and "loaded" or ("FAILED - " .. tostring(errB))))
end
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local UserInputService = game:GetService("UserInputService")
-- phone-safe: some mobile executors inject before the local player replicates
local LocalPlayer = Players.LocalPlayer
local waitedPlr = 0
while not LocalPlayer and waitedPlr < 240 do
    task.wait(0.05)
    waitedPlr += 1
    LocalPlayer = Players.LocalPlayer
end
if not LocalPlayer then
    error("[Untitled Cheat v2] could not find LocalPlayer - rejoin and relaunch")
end
LocalPlayer:WaitForChild("PlayerGui", 10)
