    CurveSidePos = true,   -- true = curl one way; false = mirror
    CurveOnAimed = true,   -- apply curve to aimed (volley/flick) shots
    CurveBounce = true,    -- banana bound: the curl bends through the hop
    UseFOVGoal = true,     -- camera view cone decides which goal to aim at
    FOVDegrees = 55,       -- acceptance half-angle around camera look
    Humanize = true,       -- jitter aim + vary curve/charge per shot
