--==============================================================
-- MODULE RESOLVER
--==============================================================
local Cache = {}
local function M(name)
    if Cache[name] then return Cache[name] end
    for _, d in ipairs(ReplicatedStorage:GetDescendants()) do
        if d:IsA("ModuleScript") and d.Name == name then
            local ok, mod = pcall(require, d)
            if ok and type(mod) == "table" then
                Cache[name] = mod
                return mod
            end
        end
    end
    return nil
end
--==============================================================
-- BASIC HELPERS
--==============================================================
local function getChar() return LocalPlayer.Character end
local function getRoot(char) return char and char:FindFirstChild("HumanoidRootPart") end
local ballOwnedUntil = 0
local function hasBall()
    local owned = false
    local R = M("Renderer")
    if R then
        if type(R.IsBoundBallOwnedBy) == "function" then
            local ok, v = pcall(R.IsBoundBallOwnedBy)
            if ok and v == true then owned = true end
        end
        if not owned and type(R.GetOwnedUserId) == "function" then
            local ok, owner = pcall(R.GetOwnedUserId)
            if ok and owner == LocalPlayer.UserId and owner ~= nil and owner ~= -1199 then owned = true end
        end
        if not owned then
            local root = getRoot(getChar())
            local ballPos = nil
            if R.GetPosition then pcall(function() ballPos = R.GetPosition() end) end
            if root and ballPos and (root.Position - ballPos).Magnitude < 8 then owned = true end
        end
    end
    if owned then
        ballOwnedUntil = tick() + 8.0
        return true
    end
    if tick() < ballOwnedUntil then return true end
    return false
end
