„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â the long cache
-- kept the dribbler protecting a ball we had already lost
local ballDribbleUntil = 0
local function hasBallDribble()
    local owned = false
    local R = M("Renderer")
    if R then
        if type(R.IsBoundBallOwnedBy) == "function" then
            local ok, v = pcall(R.IsBoundBallOwnedBy)
            if ok and v == true then owned = true end
        end
        if not owned and type(R.GetOwnedUserId) == "function" then
            local ok, owner = pcall(R.GetOwnedUserId)
            if ok and owner == LocalPlayer.UserId and owner ~= nil and owner ~= -1199 then owned = true end
        end
        if not owned then
            local root = getRoot(getChar())
            local ballPos = nil
            if R.GetPosition then pcall(function() ballPos = R.GetPosition() end) end
            if root and ballPos and (root.Position - ballPos).Magnitude < 4 then owned = true end
        end
    end
    if owned then
        ballDribbleUntil = os.clock() + 0.15 -- snap off fast when lost
        return true
    end
    return os.clock() < ballDribbleUntil
end
local function getBallPosition()
	local R = M("Renderer")
	local pos
	if R and R.GetPosition then pcall(function() pos = R.GetPosition() end) end
	if not pos then
		local root = getRoot(getChar())
		local map = workspace:FindFirstChild("Map")
		local data = map and map:FindFirstChild("Data")
		local b = data and data:FindFirstChild("Ball")
		if b and b:IsA("BasePart") then pos = b.Position end
	end
	return pos
end
local function getBall()
	local R = M("Renderer")
	if R and R.GetPosition then
		local ok, b = pcall(function()
			local p = R.GetPosition()
			if p then
				for _, obj in ipairs(workspace:GetDescendants()) do
					if obj:IsA("BasePart") and obj.Position == p then
						return obj
					end
				end
			end
		end)
		if ok and b then return b end
	end
	local root = getRoot(getChar())
	if root then
		for _, obj in ipairs(workspace:GetDescendants()) do
			if obj:IsA("BasePart") and obj.Name:lower():find("Ball") then
				if (obj.Position - root.Position).Magnitude < 20 then
					return obj
				end
			end
		end
	end
	return nil
end
local function getBallVelocity()
    local R = M("Renderer")
    local R = M("Renderer")
    local vel
    if R and R.GetTargetVelocity then
        pcall(function() vel = R.GetTargetVelocity() end)
    end
    if not vel and R and R.GetVelocity then
        pcall(function() vel = R.GetVelocity() end)
    end
    return vel or Vector3.new()
end
--==============================================================
-- TEAMS + GOALS  (own logic, built on GetOpposingTeamName)
--==============================================================
local cachedTeams = nil
local cachedTeamsAt = 0
local function resolveTeams()
    if cachedTeams and os.clock() - cachedTeamsAt < 30 then return cachedTeams end
    local MS = M("MatchSettings")
    local map = workspace:FindFirstChild("Map")
    local data = map and map:FindFirstChild("Data")
    if not MS or not data then return nil end
    local ok, oppName = pcall(MS.GetOpposingTeamName, LocalPlayer)
    if not ok or type(oppName) ~= "string" then return nil end
    local oppModel = data:FindFirstChild(oppName)
    if not oppModel then return nil end
    -- own team = the other team model under Data
    local ownName = nil
    for _, c in ipairs(data:GetChildren()) do
        if c.Name ~= oppName and c.Name ~= "Ball" and c.Name ~= "Center" and c.Name ~= "Stand" and c.Name ~= "Walls" then
            local goal = c:FindFirstChild("Goal")
            if goal and goal:IsA("BasePart") then ownName = c.Name break end
        end
    end
    local attackGoal = oppModel:FindFirstChild("Goal")
    local ownGoal = ownName and data:FindFirstChild(ownName) and data[ownName]:FindFirstChild("Goal")
    if attackGoal and attackGoal:IsA("BasePart") then
        cachedTeams = {
            OppName = oppName,
            OwnName = ownName,
            AttackGoal = attackGoal,
            OwnGoal = ownGoal and ownGoal:IsA("BasePart") and ownGoal or nil,
        }
        cachedTeamsAt = os.clock()
        return cachedTeams
    end
    return nil
end
local function getOpponentGoal()
    local t = resolveTeams()
    if t and t.AttackGoal then
        local root = getRoot(getChar())
        local d = root and (root.Position - t.AttackGoal.Position).Magnitude
        -- team goal only makes sense if we are reasonably near it
        if not root or (d and d < 400) then return t.AttackGoal end
    end
    -- fallback: nearest goal by look/distance (covers practice area)
    local root = getRoot(getChar())
    local look = root and root.CFrame.LookVector or Vector3.new(0, 0, -1)
    local pos = root and root.Position or Vector3.new()
    local best, bestScore = nil, -math.huge
    for _, d in ipairs(workspace:GetDescendants()) do
        if d:IsA("BasePart") and d.Name == "Goal"
            and d.Size.X >= 15 and d.Size.Y >= 6
            and d ~= t.OwnGoal then
            local toGoal = d.Position - pos
            local dist = toGoal.Magnitude
            if dist > 5 and dist < 400 then
                local dir = toGoal / dist
                local sc = look:Dot(dir) - (dist / 500)
                if sc > bestScore then bestScore = sc; best = d end
            end
        end
    end
    if best and bestScore > -0.5 then return best end
    return nil
end
--==============================================================
-- FOV GOAL PICK (camera view cone decides which goal to aim at)
--==============================================================
local cachedGoalParts, cachedGoalPartsAt = nil, 0
local function getCachedGoalParts()
    if cachedGoalParts and os.clock() - cachedGoalPartsAt < 15 then return cachedGoalParts end
    local list = {}
