    -- props and practice rigs must never steal the pick (measured hijack:
    -- the FOV cone once locked a lobby practice goal, every shot flew at it)
    if t.AttackGoal then
        local gp = t.AttackGoal.Position
        local to = Vector3.new(gp.X - pos.X, 0, gp.Z - pos.Z)
        local dist = to.Magnitude
        if dist > 2 and dist < 400 then
            local ang = flatAngleDeg(to.Unit, lookFlat)
            if ang < cone + 25 then
                if dbg then dbg.lastFovGoal = string.format("attack@%.0fdeg", ang) end
                return t.AttackGoal
            end
        end
