-- habit steers the picker to the opposite side
local gkDiveSide = {}
local gkDiveTallied = {}
-- keeper snapshot with PREDICTION support: blend the physics velocity with
-- the observed displacement over the last read so dives, sprint stops and
-- resets all feed the range checker with a real motion vector
local function buildGkInfo(r)
    if not r then return nil end
    local nowT = time()
    local prev = gkTrack[r]
    local vel = r.AssemblyLinearVelocity or Vector3.new()
    local flat = Vector3.new(vel.X, 0, vel.Z)
    if prev and nowT - prev.t > 0.05 and nowT - prev.t < 1.2 then
        local o = (r.Position - prev.pos) / (nowT - prev.t)
        flat = flat * 0.5 + Vector3.new(o.X, 0, o.Z) * 0.5
    end
    gkTrack[r] = { pos = r.Position, t = nowT }
    if (nowT - (gkTrack.gc or 0)) > 30 then
        for k in pairs(gkTrack) do
            if typeof(k) == "Instance" and not k.Parent then gkTrack[k] = nil end
        end
        gkTrack.gc = nowT
    end
    -- REAL DIVE STATE (live packet tracking): mid-dive = committed body in
    -- flight (no new save reach); recovering = inside the repeat delay,
    -- cannot dive at all. The blended velocity already carries the dive
    -- motion for the oval sweep and the predicted spot.
    local nowS = workspace:GetServerTimeNow()
    local diving, recovering = false, false
    local charOf = r.Parent
    local dive = charOf and gkDiveTrack[charOf] or nil
    if dive then
        if nowS < dive.untilT then diving = true
        elseif nowS < dive.recoverAt then recovering = true
        end
    end
