-- A 100ms staleness is ~0.3 studs of keeper drift; the picker predicts
-- their motion regardless, so a fresh-but-stale reading is safe.
local gkInfoMemo, gkInfoMemoAt = nil, 0
local function getGoalieInfo(goal)
    if not goal then return nil end
    local nowC = os.clock()
    local key = tostring(goal)
    if gkInfoMemo and gkInfoMemo.key == key and nowC - gkInfoMemoAt < 0.10 then
        return gkInfoMemo.info
    end
    local info = getGoalieInfoRaw(goal)
    gkInfoMemo, gkInfoMemoAt = { key = key, info = info }, nowC
    return info
end
