-- sampled polyline and ray-check every segment. Arc-class lanes (past
-- LongRange) get the same compensated pitch the arc solve will choose;
-- short lanes get the plain drooping launch.
local DR_FLIGHT_DT = 0.07 -- polyline sample spacing (seconds)
local function drFlightPolyline(origin, target, inheritFlat)
    inheritFlat = inheritFlat or Vector3.new()
    local flat = Vector3.new(target.X - origin.X, 0, target.Z - origin.Z)
    if flat.Magnitude < 0.8 then return { origin, target } end
    flat = flat.Unit
    local dist = (target - origin).Magnitude
    local arcClass = dist > (State and State.LongRange or 40)
    local tC = math.max(drFlightTime(dist), 0.05)
    -- compensated launch vertical for arc-class lanes (the arc solve's own
    -- target: arrive at target.Y by tC); plain drooped launch below it
    local vy0 = arcClass
        and ((target.Y - origin.Y + 50 * tC * tC) / tC)
        or ((target.Y - origin.Y) / dist * LAUNCH_SPEED_EST)
    local maxUp = 0.55 * LAUNCH_SPEED_EST -- pitch stays inside the 30g clamp
    vy0 = math.clamp(vy0, -maxUp, maxUp)
    local v = flat * LAUNCH_SPEED_EST
        + Vector3.new(0, vy0, 0)
        + Vector3.new(inheritFlat.X or 0, 0, inheritFlat.Z or 0)
    local pts = { origin }
    local pos = origin
    local tEnd = math.min(tC, 0.85) -- full wall coverage of every managed lane (<=70 studs)
    local t = 0
    while t < tEnd - 1e-4 do
        local dt = math.min(DR_FLIGHT_DT, tEnd - t)
        v = v * math.exp(-0.5 * dt) + Vector3.new(0, -100 * dt, 0)
        pos = pos + v * dt
        table.insert(pts, pos)
        t += dt
    end
    pts[#pts] = target -- final segment rides into the aim point itself
    return pts
end
