    -- the polyline only earns its rays on far or rising flights
    local flatD = Vector3.new(target.X - origin.X, 0, target.Z - origin.Z).Magnitude
    if flatD < 25 and math.abs(target.Y - origin.Y) < 4 then return false end
    local pts = drFlightPolyline(origin, target, inheritFlat)
    for i = 2, #pts do
        if drLaneBlocked(pts[i - 1], pts[i]) then return true end
    end
    return false
end
