-- lane only ranks safe when the ball stays clear of the whole swept
-- predictor hitbox across the window. Humans catch with the same oval.
local GK_CONTACT_WINDOW = 0.875 -- SaveWindowSeconds: the save lives the whole dive
local GK_CONTACT_STEP = 0.06
local GK_CONTACT_SKIP = 0.05 -- ball still in the kick anim at its very start
local GK_RECEIVE_RADIUS = 4.5 -- SaveReach 2 + Padding 1.5 + assist tolerance
local GK_RECEIVE_LOW = 2.6    -- oval reaches this far below the root (feet)
local GK_RECEIVE_HIGH = 1.4   -- and this far above it (hands)
local function drKeeperContactSeg(gkInfo, segs)
    if not (gkInfo and gkInfo.pos) then return math.huge, math.huge end
    local root0 = gkInfo.pos
    local kvel = gkInfo.vel or Vector3.new()
    local flatK = Vector3.new(kvel.X, 0, kvel.Z)
    local vy0 = gkInfo.vy or 0 -- a keeper jumping AT the ball raises the oval
    local flightEnd = 0
    for _, s in ipairs(segs) do
        flightEnd = math.max(flightEnd, s[3] + s[4])
    end
    local tEnd = math.min(GK_CONTACT_WINDOW, flightEnd)
    local best, bestT = math.huge, math.huge
    local t = GK_CONTACT_SKIP
    while t <= tEnd + 1e-6 do
        local bp
        for _, s in ipairs(segs) do
            if t >= s[3] and t <= s[3] + s[4] + 1e-6 then
                local f = (s[4] > 1e-6) and math.min((t - s[3]) / s[4], 1) or 0
                bp = s[1]:Lerp(s[2], f)
                break
            end
        end
        if bp then
            local jg = gkInfo.jg or 100
            local jumpDy = math.clamp(vy0 * t - 0.5 * jg * t * t, -4, 4)
            -- HANDS-FORWARD OVAL: the receive hitbox rides slightly in
            -- front of the chest, along where the keeper is looking
            local kr = root0 + flatK * t + Vector3.new(0, jumpDy, 0)
            local lookV = gkInfo.look
            if lookV and lookV.Magnitude > 0.05 then
                kr = kr + lookV.Unit * 0.8
            end
            local dyy = bp.Y - kr.Y
            local dFlat = Vector3.new(bp.X - kr.X, 0, bp.Z - kr.Z).Magnitude
            -- exposed surface distance from this flight sample to the oval
            local raw
            if dyy < -GK_RECEIVE_LOW or dyy > GK_RECEIVE_HIGH then
                local vy = dyy > 0 and (dyy - GK_RECEIVE_HIGH) or (dyy + GK_RECEIVE_LOW)
                -- ANISOTROPIC REACH + DIVE ALIGNMENT: the arms extend ~2
