-- unnamed collidables (goal frames, meshed props) stay out, their
-- retention constants would not be trustworthy reflections.
--==============================================================
local function drBankWalls(goal)
    local now = os.clock()
    local memo = _G.__SR_BANK_MEMO
    if memo and memo.goal == goal and now - memo.at < 2 then return memo.list end
    local out = {}
    if goal then
        for _, obj in ipairs(workspace:GetDescendants()) do
            if obj ~= goal and obj:IsA("BasePart") and obj.Anchored and obj.CanCollide then
                local nm = string.lower(obj.Name or "")
                local kind
                if string.find(nm, "barricade", 1, true) or string.find(nm, "barrier", 1, true)
                    or string.find(nm, "plexi", 1, true) or string.find(nm, "glass", 1, true) then
                    kind = "bar"
                elseif string.find(nm, "wall", 1, true) or string.find(nm, "board", 1, true) then
                    kind = "wall"
                end
                if kind and not string.find(nm, "goal", 1, true) and not string.find(nm, "net", 1, true)
                    and not string.find(nm, "post", 1, true) and not string.find(nm, "crossbar", 1, true)
                    and not string.find(nm, "cross", 1, true) and not string.find(nm, "frame", 1, true) then
                    local s = obj.Size
                    local faceArea = math.max(s.X * s.Y, s.Y * s.Z, s.X * s.Z)
                    if faceArea >= 14 then
                        local d = (obj.Position - goal.Position).Magnitude
                        if d < 70 then
                            table.insert(out, { pos = obj.Position, cf = obj.CFrame, size = s, kind = kind, d = d })
                        end
                    end
                end
            end
        end
        table.sort(out, function(a, b) return a.d < b.d end)
        while #out > 3 do table.remove(out) end
    end
    _G.__SR_BANK_MEMO = { goal = goal, at = now, list = out }
    return out
end
local function computeScorableCorner(goal, gkInfo, volOnly, wantBank, isVolShot, originOverride)
    -- PERF CANARY: real milliseconds per full pick (coarse + refinements);
    -- the "slow as hell" verdict gets data instead of guesses
    local tPk0 = os.clock()
    local function tPk()
        local msPick = (os.clock() - tPk0) * 1000
        local prevPk = _G.__ISS_DEBUG and tonumber(_G.__ISS_DEBUG.pickerMs) or nil
        _G.__ISS_DEBUG.pickerMs = prevPk
            and string.format("%.1f", prevPk * 0.8 + msPick * 0.2)
            or string.format("%.1f", msPick)
    end
    local cf = goal.CFrame
    local right = cf.RightVector
    local up = cf.UpVector
    local lv = cf.LookVector
    local pos = goal.Position
    local halfW = math.max(goal.Size.X * 0.5, 4)
    local halfH = math.max(goal.Size.Y * 0.5, 2)
