    -- lanes (the far side + high) beat the retreat; the margins tighten
    local keeperRush = false
    if gkInfo and gkInfo.pos and root then
        local latGK = math.abs((gkInfo.pos - pos):Dot(right))
        if latGK < 6 then postM = 2.3 end
        local dGoal = (gkInfo.pos - pos).Magnitude
        if dGoal > 9 and gkInfo.vel and gkInfo.vel.Magnitude > 10 then
            local toUsV = root.Position - gkInfo.pos
            if toUsV.Magnitude > 0.5 then
                keeperRush = gkInfo.vel:Dot(toUsV.Unit) > 8 -- running AT us
            end
        end
        if keeperRush then postM = 2.0 end
    end
    local insetX = postM
