    -- goal + origin inside 60ms resolves from the last computed pick
    local memoKey = tostring(goal) .. "|" .. string.format("%.1f,%.1f", origin.X, origin.Z)
        .. "|fb" .. tostring((State.ForceBounceUntil or 0) > os.clock())
        .. "|wb" .. tostring(wantBank == true)
        .. "|vol" .. tostring(isVolShot == true)
    local memo = _G.__SR_PICK_MEMO
    if memo and memo.key == memoKey and os.clock() - memo.at < 0.15 then
        State.AimContactGap = memo.aimGap
        return memo.bestPos, memo.bestName, memo.bestSide, memo.bestOpen,
            memo.bestFut, memo.allBlocked, memo.bestBounce
    end
    local shootDist = (origin - pos).Magnitude
    local tFly = math.max(shootDist / LAUNCH_SPEED_EST, 0.12)
    -- mouth face: the goal's near end cap (ground-bounce hops sit in FRONT
    -- of this plane so the ball can bound across it)
    local faceNear = pos + lv * (goal.Size.Z * 0.5)
    if (origin - faceNear).Magnitude > (origin - (pos - lv * (goal.Size.Z * 0.5))).Magnitude then
        faceNear = pos - lv * (goal.Size.Z * 0.5)
    end
    local nF = Vector3.new(faceNear.X - pos.X, 0, faceNear.Z - pos.Z)
    nF = (nF.Magnitude > 0.05) and nF.Unit or nil
