    -- dive instead of chest balls the keeper's solver eats for fun.
    local thinBias = 0
    if gkInfo and gkInfo.pos then
        local tC0 = math.max(drFlightTime(shootDist), 0.12)
        local fut0 = gkInfo.pos + (gkInfo.vel or Vector3.new()) * tC0
        local dxf0 = Vector3.new(pos.X - fut0.X, 0, pos.Z - fut0.Z).Magnitude
        local cov0 = (gkInfo.diving or gkInfo.recovering) and 0 or gkReach(tC0)
        if math.sqrt(dxf0 * dxf0 + (pos.Y - fut0.Y) ^ 2) - cov0 < 2.0 then
            thinBias = 1.4
        end
