    -- pick onto the fake side (poles / keeper-center shots with bait on).
    -- The side locks on the FIRST read of each charge (mouse down) and the
    -- stored value still covers the release-time computes after mouse-up.
    local chargingNow = false
    pcall(function()
        chargingNow = UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)
    end)
    local sideLock = _G.__ISS_SIDE_LOCK
    if os.clock() - (sideLock and sideLock.at or 0) > 8 then sideLock = nil end
    if not chargingNow then
        if sideLock then sideLock.armed = false end
    elseif not (sideLock and sideLock.armed) then
        _G.__ISS_SIDE_LOCK = { at = os.clock(), half = cursorHalf, armed = true }
        sideLock = _G.__ISS_SIDE_LOCK
    end
    if sideLock and sideLock.armed then
        cursorHalf = sideLock.half
    end
