    -- vs a grounded keeper every bounce is a low skip they just eat
    local keeperAir = false
    if gkInfo and gkInfo.pos then
        local tCg = math.max(drFlightTime(shootDist), 0.12)
        local gy = gkInfo.pos.Y + math.clamp((gkInfo.vy or 0) * tCg, -2.5, 2.5)
        -- a RISING keeper (the auto keeper's HighBallJumps behavior) is
        -- airborne at arrival: the bound sneaks under the jumped body
        keeperAir = ((gy - (pos.Y - goal.Size.Y * 0.5)) >= 2.5)
            or (gkInfo.diving == true)
            or ((gkInfo.vy or 0) > 5)
    end
