    -- fallback only when Auto Bounce is toggled off
    local autoHop, autoClose, autoFar
    if State.AutoBounce ~= false then
        local react = (SR_CALIB.gkReact or GK_REACT_SECONDS) + 0.06
        -- CLOSE: the envelope where the ball arrives inside their reaction
        -- clock (damped-flight inverse: d = 2*v0*(1 - e^(-thr/2)))
        autoClose = math.clamp(2 * LAUNCH_SPEED_EST * (1 - math.exp(-react / 2)), 10, 48)
        -- FAR: the long rule, extended while they cannot dive again
        autoFar = math.max(BOUNCE_RANGE, (State.LongRange or 40) + 6)
        if gkInfo and (gkInfo.recovering or gkInfo.diving) then
            autoFar = autoFar + 14
        end
        -- HOP: shaped by the body state at arrival
        if keeperAir then
            autoHop = 0.8 -- skims under the airborne body
        elseif gkInfo and gkInfo.recovering then
            autoHop = 1.3 -- mid-low while they're on the deck
        else
            autoHop = 1.6 -- grounded stand: the proven mid-arc skip
