    --               to force parries, fumbles and misreads
    local bMode = State.BounceMode or "Smart"
    if volOnly == false then
        if bMode == "Pressure" then
            bounceAllowed = true
        elseif bMode == "Sometimes"
            and (State.ForceBounceUntil or 0) <= os.clock() then
            local key = math.floor(shootDist) * 7 + math.floor(os.clock() * 2)
            bounceAllowed = bounceAllowed and ((key % 3) == 0)
        elseif bMode == "Jump" and not keeperAir then
            bounceAllowed = false
        elseif bMode == "Bait"
            and (State.ForceBounceUntil or 0) <= os.clock()
            and not (gkInfo and (gkInfo.diving or gkInfo.recovering)) then
            bounceAllowed = false
        end
    end
    _G.__ISS_DEBUG.lastBounceGate = bMode .. "=" .. tostring(bounceAllowed)
    local bounceRange = math.max(autoFar or (State.BounceMaxRange or BOUNCE_RANGE), (State.LongRange or 40) + 6)
    if (State.BounceMode or "Smart") == "Pressure" then
        bounceRange = 999 -- full-attack: bounds allowed at every distance
    end
