    -- lateral direction on the goal's right axis (dedup by the dive's
    -- started timestamp so coarse/refine passes don't multi-count)
    do
        local kc = gkInfo and gkInfo.char
        if kc and gkInfo.diving and gkInfo.diveStarted
            and gkInfo.vel and not gkDiveTallied[gkInfo.diveStarted] then
            gkDiveTallied[gkInfo.diveStarted] = true
            local latD = Vector3.new(gkInfo.vel.X, 0, gkInfo.vel.Z):Dot(right)
            if math.abs(latD) > 2 then -- a real lateral commit, not a straight hop
                local side = (latD > 0) and "R" or "L"
                local tally = gkDiveSide[kc] or { R = 0, L = 0 }
                tally[side] = tally[side] + 1
                gkDiveSide[kc] = tally
                local nT = 0
                for _ in pairs(gkDiveTallied) do nT = nT + 1 end
                if nT > 64 then gkDiveTallied = {} end
            end
        end
    end
