            local kt = gkInfo.char and gkDiveSide[gkInfo.char] or nil
            if kt then
                local tot = kt.R + kt.L
                if tot >= 3 then
                    if kt.R > kt.L * 2 and sf < -0.15 then
                        score = score + 2.2
                    elseif kt.L > kt.R * 2 and sf > 0.15 then
                        score = score + 2.2
                    end
                end
            end
        else
            -- no keeper reading: favor decisive cross corners
            score = math.abs(sf) * 10 + (hf > 0 and 3 or 0)
        end
