        -- rotation so the keeper sees every band over a match
        local variety = 1.0
        if recentPick
            and math.abs(sf - recentPick.sf) < 0.12
            and math.abs(hf - recentPick.hf) < 0.12 then
            score = score - 2.5 * variety
        elseif recentPick
            and (recentPick.sf > 0) ~= (sf > 0) and math.abs(sf) > 0.5 then
            score = score + 0.8 * variety
        end
        if recentPick and type(recentPick.hf) == "number" then
            score = score + math.abs(hf - recentPick.hf) * 1.2 * variety -- height rotation
