Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â this runs
        -- at shot time only (bankOn), never in the per-frame reticle.
        if bankOn then
            for _, wl in ipairs(drBankWalls(goal)) do
                -- STRIKING FACE: the board face that looks back at the
                -- shot origin; floor/ceiling faces don't bank (the ground
                -- bound already owns those)
                local axes = { wl.cf.RightVector, wl.cf.UpVector, wl.cf.LookVector }
                local kinds = { "X", "Y", "Z" }
                local bestAi, bestS, bestDot = nil, 0, -math.huge
                local toShot = Vector3.new(origin.X - wl.pos.X, 0, origin.Z - wl.pos.Z)
                for ai = 1, 3 do
                    if ai ~= 2 then
                        for _, sgn in ipairs({ 1, -1 }) do
                            local dot = (axes[ai] * sgn):Dot(toShot)
                            if dot > bestDot then bestDot, bestAi, bestS = dot, ai, sgn end
                        end
                    end
                end
                if bestDot > 0.25 then
                    local n = axes[bestAi] * bestS
                    local P0 = wl.pos + n * wl.size[kinds[bestAi]] * 0.5 -- face plane
                    if (origin - P0):Dot(n) > 0 then
                        -- reflect the mouth target through the face and take
                        -- the specular contact; the retention skews the
                        -- outgoing leg, so a short fixed point walks the
                        -- contact along the face until the rebound lands on
                        -- the aimed corner
                        local Tm = p - n * (2 * ((p - P0):Dot(n)))
                        local rayU = (Tm - origin).Unit
                        local rc = rayU:Dot(n)
                        if rc < -0.05 then
                            local hitD = (P0 - origin):Dot(n) / rc
                            if hitD > 2.0 then
                                local P = origin + rayU * hitD
                                local onFace = true
                                for ai = 1, 3 do
                                    if ai ~= bestAi then
                                        if math.abs((P - wl.pos):Dot(axes[ai])) > wl.size[kinds[ai]] * 0.5 + 1.2 then
                                            onFace = false
                                            break
                                        end
                                    end
                                end
                                if onFace then
                                    local isBarr = wl.kind == "bar"
                                    local retN = isBarr and 0.9 or 0.58
                                    local retT = isBarr and 0.8 or 0.38
                                    local outV = nil
                                    for _ = 1, 3 do
                                        local inc = (P - origin).Unit
                                        local vin = inc:Dot(n)
                                        if vin >= -0.05 then outV = nil break end -- grazing: no bank
                                        local ramp = math.clamp((math.abs(vin) * LAUNCH_SPEED_EST - 5) / 75, 0, 1)
                                        outV = (inc - n * vin) * (1 - (1 - retT) * ramp)
                                            + n * math.abs(vin) * retN * ramp
                                        local leg2v = p - P
                                        local miss = leg2v - outV.Unit * leg2v.Magnitude
                                        miss = miss - n * miss:Dot(n)
                                        P = P + miss * 0.7
                                        for ai = 1, 3 do
                                            if ai ~= bestAi then
                                                local half2 = wl.size[kinds[ai]] * 0.5
                                                local comp = (P - wl.pos):Dot(axes[ai])
                                                P = P + axes[ai] * (math.clamp(comp, -half2 - 0.8, half2 + 0.8) - comp)
                                            end
                                        end
                                    end
                                    if outV then
                                        local outSpd = outV.Magnitude * LAUNCH_SPEED_EST
                                        local predict = P + outV.Unit * (p - P).Magnitude
                                        if outSpd > 18 and (p - predict).Magnitude <= 2.2 then
                                            local dLeg1 = (P - origin).Magnitude
                                            local P2 = P + n * 2.2 -- face clearance for leg 2
                                            local dLeg2 = (p - P2).Magnitude
                                            local t1 = math.max(drFlightTime(dLeg1), 0.06)
                                            local t2 = math.max(dLeg2 / math.max(outSpd, 18), 0.06)
                                            local tTot = t1 + 0.03 + t2
                                            if dLeg1 + dLeg2 < shootDist * 1.4 -- sane detour
                                                and not drLanePathBlocked(origin, P, inheritFlat)
                                                and not drLaneBlocked(P2, p) then
                                                local scoreK = 0
                                                local marginK
                                                if gkInfo and gkInfo.pos then
                                                    local gkVel = gkInfo.vel or Vector3.new()
                                                    local futK = gkInfo.pos + gkVel * tTot
                                                    local dxfK = Vector3.new(p.X - futK.X, 0, p.Z - futK.Z).Magnitude
                                                    local dyK = (p.Y - futK.Y) * 1.35
                                                    marginK = math.sqrt(dxfK * dxfK + dyK * dyK)
                                                        - ((gkInfo.diving or gkInfo.recovering) and 0 or gkReach(tTot))
                                                    scoreK = marginK * 2.2 - tTot * 3.5 -- same ranking scale
                                                else
                                                    scoreK = math.abs(sf) * 10
                                                end
                                                scoreK = scoreK + math.abs(sf) * 2.0
                                                if math.abs(sf) < 0.35 then
                                                    scoreK = scoreK - 2.0
                                                end
                                                scoreK = scoreK + 1.0 -- the board read costs the keeper half a beat
                                                local contactGapK, contactGapKT
                                                if gkInfo and gkInfo.pos then
                                                    contactGapK, contactGapKT = drKeeperContactSeg(gkInfo, {
                                                        { origin, P, 0, t1 },
                                                        { P2, p, t1 + 0.03, t1 + 0.03 + t2 },
                                                    })
                                                    if contactGapK <= 1.2 then
                                                        scoreK = scoreK - 55 + math.max(contactGapK, -4.0)
                                                    elseif contactGapK <= 2.4 then
                                                        scoreK = scoreK - (16 + (2.4 - contactGapK) * 12)
                                                    else
                                                        scoreK = scoreK + math.min(contactGapK - 2.4, 3.0) * 1.6
                                                    end
                                                end
                                                if scoreK > bestScore then
                                                    bestScore = scoreK
                                                    bestPos = P -- the aim target IS the board point
                                                    bestName = string.format("bank_%s_%s",
                                                        isBarr and "bar" or "wall",
                                                        sf < -0.5 and "left" or (sf > 0.5 and "right" or "center"))
                                                    bestSide = sf >= 0 and 1 or -1
                                                    bestSF, bestHF = sf, hf
                                                    bestContact, bestContactT = contactGapK, contactGapKT
                                                    if gkInfo and gkInfo.pos then
                                                        bestOpen = marginK
                                                        bestFut = fut
                                                    end
                                                    bestBounce = true -- banks ride the bounce path: no curve, no mouth clamp
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end
    for _, sf in ipairs(sides) do
        for _, hf in ipairs(heights) do
            scoreCandidate(sf, hf)
