    -- finally falls onto the ground, through the same flight model
    local land = drFlightGroundEx(origin, heading, tanA, speed, inh, netSpinY or 0, g, math.min(1.5, target.Y), 4)
    _G.__ISS_DEBUG.lastArc = string.format(
        "d=%.0f h=%.1f v=%.0f g=%.0f spin=%.1f theta=%.1fdeg fly=%.2fs yaw=%.2fdeg lat=%.1f inh=%.1f,%.1f planeMiss=%.2f " ..
        "falls=%.1f,%.1f,%.1f %s",
        d, h, speed, g, netSpinY or 0, math.deg(math.atan(tanA)), fly, yawDeg, latOff,
        inh.X, inh.Z,
        heightAt and (heightAt - target.Y) or 0,
        land and land.X or 0, land and land.Y or 0, land and land.Z or 0,
        unreachable and "UNREACHABLE" or (heightAt and math.abs(heightAt - target.Y) < 0.12 and "ON TARGET" or (disc >= 0 and "tuned" or "MAXRANGE")))
    return dir3D, heading
end
-- inherited counter-steer for the straight (non-arc) lane: the server adds
-- the kicker's flat velocity to the launch on every kick, which otherwise
-- pushes short shots off-corner too. Rotate the aim heading into the drift.
local function drCounterSteer(flatDir, d, root)
    if not root or d < 6 then return flatDir end
    local vel = root.AssemblyLinearVelocity or Vector3.new()
    local inh = Vector3.new(vel.X, 0, vel.Z)
    local lat = inh:Dot(Vector3.new(-flatDir.Z, 0, flatDir.X))
    if math.abs(lat) < 0.5 then return flatDir end
    local flightT = d / math.max(ARC.maxSpeed or 123, 10)
    local yawA = math.clamp(lat * flightT / d, -0.5, 0.5)
    local c, s = math.cos(yawA), math.sin(yawA)
    local h = Vector3.new(flatDir.X * c + flatDir.Z * s, 0, -flatDir.X * s + flatDir.Z * c)
    if h.Magnitude < 0.05 then return flatDir end
    return h.Unit
end
-- FLIGHT RECORDER: sample the replicated (server-authoritative) ball after
