local flightHistory = {}
local function recordFlight(tag, launch, goal, aimPoint, isBounce, isArc, inputNet, crossRef)
    task.spawn(function()
        local visuals = workspace:FindFirstChild("Misc")
        visuals = visuals and visuals:FindFirstChild("Visuals")
            or workspace:FindFirstChild("Visuals")
        if not visuals then return end
        local gf = goal.CFrame
        local flatOut = Vector3.new(launch.X - goal.Position.X, 0, launch.Z - goal.Position.Z)
        if flatOut.Magnitude < 0.1 then return end
