        -- the shooter's run-up adds along-axis speed the nomogram ignores;
        -- capture it once so the calibration is fair regardless of sprinting
        local root0 = getRoot(getChar())
        local along = 0
        if root0 then
            local vel = root0.AssemblyLinearVelocity or Vector3.new()
            along = vel:Dot(flatOut)
        end
        local depth = math.abs(flatOut:Dot(gf.RightVector)) * goal.Size.X * 0.5
            + math.abs(flatOut:Dot(gf.LookVector)) * goal.Size.Z * 0.5
        local planePos = goal.Position + flatOut * depth
        local distPlane = (launch - planePos).Magnitude
        local planeLat = flatOut:Cross(Vector3.new(0, 1, 0))
        local halfW = goal.Size.X * 0.5
        local topY = goal.Position.Y + goal.Size.Y * 0.5
        local botY = goal.Position.Y - goal.Size.Y * 0.5
        local prev = {}
        local t0 = nil -- anchor: the redirect's velocity jump
        local vel0 = nil -- the pre-launch tracked velocity
        local deadline = time() + 4.0
        while time() < deadline do
            for _, ball in ipairs(visuals:GetChildren()) do
                if ball:IsA("BasePart") and string.sub(ball.Name, 1, 10) == "ClientBall" then
                    local p = ball.Position
                    local last = prev[ball]
                    prev[ball] = p
                    if last then
