                            -- actually drove
                            if aimPoint and not isBounce and not isVolTag
                                and math.abs(latErr) < 8 then
                                if isArc then
                                    if inp >= 0.25 then
                                        SR_CALIB.latKArc = math.clamp(
                                            SR_CALIB.latKArc * 0.7 + (latErr / inp) * 0.3, -20, 20)
                                        SR_CALIB.n += 1
                                    end
                                else
                                    if math.abs(inp) < 0.1 then
                                        SR_CALIB.latBase = math.clamp(
                                            SR_CALIB.latBase * 0.7 + latErr * 0.3, -2.5, 2.5)
                                        SR_CALIB.n += 1
                                    elseif inp >= 0.25 then
                                        SR_CALIB.latKStr = math.clamp(
                                            SR_CALIB.latKStr * 0.7 + (latErr / inp) * 0.3, -20, 20)
                                        SR_CALIB.n += 1
                                    end
                                end
                            end
