                            -- into the hop pre-shift next to the bow model
                            if isBounce and crossRef and math.abs(inputNet or 0) >= 0.25 then
                                local latRef = (crossRef - planePos):Dot(planeLat)
                                local latErrB = lat - latRef
                                if math.abs(latErrB) < 8 then
                                    SR_CALIB.latKB = math.clamp(
                                        (SR_CALIB.latKB or 0) * 0.7
                                            + (latErrB / (inputNet or 1)) * 0.3, -20, 20)
                                    SR_CALIB.n += 1
                                end
                            end
