    -- bows swerved 15-27 studs wide (measured) and died outside the frame.
    -- Demand fades by range: full inside 55 studs, nothing by 75.
    local capFade = (d > 55) and math.clamp((75 - d) / 20, 0, 1) or 1
    mag = mag * capFade
    local acg = State.AimContactGap
    if acg and acg < 2.5 then
        mag = mag * 1.35
    end
    if mag < 0.08 then
        mag = 0 -- not needed: don't curve
    end
    if State.Humanize ~= false and math.random() < 0.2 then
        mag = mag * 0.55 -- occasional soft curl so the shape varies per shot
    end
