--==============================================================
task.spawn(function()
    while State.Alive do
        task.wait(0.5)
        pcall(function()
        local Sprint = M("Sprint")
        local char = LocalPlayer.Character
        if char and Sprint then
            if State.InfStamina then
                pcall(Sprint.SetUnlimitedStamina, char, "ISSuite", true)
                pcall(Sprint.SetStaminaMultiplier, 100)
            else
                pcall(Sprint.SetUnlimitedStamina, char, "ISSuite", false)
                pcall(Sprint.ClearUnlimitedStaminaSource, "ISSuite")
            end
        end
        end)
    end
end)
--==============================================================
-- CURVE AMPLIFICATION (guarded per process)
--==============================================================
if not _G.__CK_ORIG then
    task.spawn(function()
        pcall(function()
        local ck = nil
        for _ = 1, 50 do
            ck = M("CurvedKicks")
            if ck then break end
            task.wait(0.2)
        end
        if not ck or type(ck.GetPower) ~= "function" then return end
        _G.__CK_ORIG = ck.GetPower
        local orig = _G.__CK_ORIG
        ck.GetPower = function(...)
            local base = orig(...)
            local st = _G.__IS_STATE
            local mult = (st and st.CurveAmp) or 200
            if type(base) == "number" then return base * mult end
            return base
        end
        if type(ck.IsEnabled) == "function" then
            ck.IsEnabled = function(...) return true end
        end
        end)
    end)
end
--==============================================================
-- BALL ESP
--==============================================================
local trackedBall = nil
local ballHighlight = nil
local ballLabel = nil
local function findBall()
    local map = workspace:FindFirstChild("Map")
    local data = map and map:FindFirstChild("Data")
    local b = data and data:FindFirstChild("Ball")
    if b and b:IsA("BasePart") then return b end
    for _, d in ipairs(workspace:GetDescendants()) do
        if d:IsA("BasePart") and (d.Name == "Ball" or d.Name:lower():find("ball")) then
            return d
        end
    end
    return nil
end
local function setupBallESP(ball)
    if not ball then return end
    trackedBall = ball
    local hl = ball:FindFirstChild("BallESP")
    if not hl then
        hl = Instance.new("Highlight")
        hl.Name = "BallESP"
        hl.FillColor = Color3.fromRGB(255, 255, 0)
        hl.OutlineColor = Color3.fromRGB(255, 215, 0)
        hl.FillTransparency = 0.3
        hl.OutlineTransparency = 0
        hl.Adornee = ball
        hl.Parent = ball
    end
    local bg = ball:FindFirstChild("BallLabel")
    if not bg then
        bg = Instance.new("BillboardGui")
        bg.Name = "BallLabel"
        bg.Size = UDim2.new(0, 110, 0, 40)
        bg.StudsOffset = Vector3.new(0, 3.5, 0)
        bg.AlwaysOnTop = true
        bg.Parent = ball
        local txt = Instance.new("TextLabel")
        txt.Size = UDim2.new(1, 0, 1, 0)
        txt.BackgroundTransparency = 1
        txt.Text = "BALL"
        txt.TextColor3 = Color3.fromRGB(255, 255, 0)
        txt.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
        txt.TextStrokeTransparency = 0
        txt.Font = Enum.Font.GothamBold
        txt.TextSize = 14
        txt.Parent = bg
    end
    ballHighlight = hl
    ballLabel = bg
end
task.spawn(function()
    while State.Alive do
        pcall(function()
        local b = findBall()
        if b and b ~= trackedBall then setupBallESP(b) end
        if ballHighlight then ballHighlight.Enabled = State.BallESP end
        if ballLabel then ballLabel.Enabled = State.BallESP end
        _G.__ISS_DEBUG.ballOwned = hasBall() and "YES" or "no"
        end)
        task.wait(0.5)
    end
end)
