€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â damped integration with gravity,
-- bounce + curve spin. Not dots, won't lag. Turns green when
-- path enters the opponent goal mouth.
--==============================================================
if not _G.__ISS_BALLPATH_HOOKED then
    _G.__ISS_BALLPATH_HOOKED = true
    _G.__ISS_BUILD = "untitled-cheat-v2"
    _G.__ISS_BALLPATH_STATE = { alive = true, runs = 0, ball = "?", lastErr = nil }
    local bpFolder = Instance.new("Folder")
    bpFolder.Name = "ISSBallPath"
    bpFolder.Parent = workspace
    local beams = {}
    local MAX_SEGS = 8
    for i = 1, MAX_SEGS do
        local a0 = Instance.new("Attachment")
        local a1 = Instance.new("Attachment")
        local b = Instance.new("Beam")
        b.Attachment0 = a0
        b.Attachment1 = a1
        b.Width0 = 0.35
        b.Width1 = 0.35
        b.Color = ColorSequence.new(Color3.fromRGB(0, 160, 255))
        b.FaceCamera = true
        b.LightInfluence = 0
        b.Parent = bpFolder
        a0.Parent = bpFolder
        a1.Parent = bpFolder
        beams[i] = { a0 = a0, a1 = a1, b = b }
    end
    local RunService = game:GetService("RunService")
    local acc = 0
    RunService.Heartbeat:Connect(function(dt)
        acc += dt
        if acc < 0.045 then return end
        acc = 0
        local bpOk, bpErr = pcall(function()
            if not State.BallPath then
                bpFolder.Parent = nil
                return
            end
            local pos = getBallPosition()
            local rawVel = getBallVelocity()
            local vel
            if typeof(rawVel) == "Vector3" then
                vel = rawVel
            elseif type(rawVel) == "table" then
                local okC, cv = pcall(Vector3.new,
                    tonumber(rawVel.X) or tonumber(rawVel[1]) or 0,
                    tonumber(rawVel.Y) or tonumber(rawVel[2]) or 0,
                    tonumber(rawVel.Z) or tonumber(rawVel[3]) or 0)
                vel = okC and cv or Vector3.new()
            else
                vel = Vector3.new()
            end
            if not pos then
                _G.__ISS_BALLPATH_STATE.ball = "not-found"
                bpFolder.Parent = nil
                return
            end
            _G.__ISS_BALLPATH_STATE.ball = "found"
            bpFolder.Parent = workspace
            _G.__ISS_BALLPATH_STATE.runs += 1
            local g = workspace.Gravity or 196.2
            local subDt = 0.03
            local maxSteps = 60
            local cp = pos
            local cv = vel
            local segments = {}
            local segStart = cp
            local goalBound = false
            local goal = getOpponentGoal()
            local gCF, halfW, gBot, gTop, gDepth
            if goal then
                gCF = goal.CFrame
                halfW = goal.Size.X * 0.5 + 1.0
                gBot = -(goal.Size.Y * 0.5 + 0.5)
                gTop = goal.Size.Y * 0.5 + 0.5
                gDepth = goal.Size.Z * 0.5 + 2.0
            end
            local segIdx = 1
            for i = 1, maxSteps do
                cv = Vector3.new(cv.X, cv.Y - g * subDt, cv.Z)
                cv = cv * math.exp(-0.4 * subDt)
                local nextP = cp + cv * subDt
                if cp.Y >= BOUNCE_CONTACT_Y and nextP.Y < BOUNCE_CONTACT_Y and cv.Y < 0 then
                    -- Hit ground: bounce
                    local hitT = (cp.Y - BOUNCE_CONTACT_Y) / (cp.Y - nextP.Y)
                    local hitP = cp + cv * subDt * hitT
                    local hitVel = cv * hitT
                    cv = Vector3.new(hitVel.X, -hitVel.Y * 0.55, hitVel.Z)
                    cp = Vector3.new(hitP.X, BOUNCE_CONTACT_Y, hitP.Z)
                    segments[#segments + 1] = { start = segStart, finish = cp }
                    segStart = cp
                else
                    cp = nextP
                end
                if cp.Y < -25 then break end
                if gCF and not goalBound then
                    local lp = gCF:PointToObjectSpace(cp)
                    if math.abs(lp.X) < halfW and lp.Y > gBot and lp.Y < gTop
                        and math.abs(lp.Z) < gDepth then
                        goalBound = true
                    end
                end
            end
            segments[#segments + 1] = { start = segStart, finish = cp }
            -- Draw beams
            for i = 1, MAX_SEGS do
                if i <= #segments then
                    beams[i].a0.Position = segments[i].start
                    beams[i].a1.Position = segments[i].finish
                    beams[i].b.Enabled = true
                else
                    beams[i].b.Enabled = false
                end
            end
            if goalBound ~= lastBound then
                local cNew = goalBound and Color3.fromRGB(90, 255, 120)
                    or Color3.fromRGB(0, 160, 255)
                for i = 1, MAX_SEGS do
                    beams[i].b.Color = ColorSequence.new(cNew)
                end
                _G.__ISS_BALLPATH_STATE.bound = goalBound
            end
            bpAtt0.Position = pos
            bpAtt1.Position = cp
        end)
        if not bpOk then
            _G.__ISS_BALLPATH_STATE.lastErr = tostring(bpErr):sub(1, 120)
        else
            _G.__ISS_BALLPATH_STATE.lastErr = nil
        end
    end)
end
-- SPEED HACK
--==============================================================
task.spawn(function()
    while State.Alive do
        task.wait(0.25)
        pcall(function()
        if State.SpeedHack then
            local char = LocalPlayer.Character
            local CC = M("CharacterControllers")
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if CC and char and hum then
                pcall(CC.SetWalkSpeed, char, hum, State.WalkSpeed)
            end
        end
        end)
    end
end)
--==============================================================
-- ANIMATION WATCHER (unique anim-id capture per player)
-- Once the tackle/kick sl animation ids are learned from a live
-- match they get wired into the dribble reaction as triggers.
--==============================================================
_G.__ISS_ANIMLOG = {}
local animSeen = {}
task.spawn(function()
    while State.Alive do
        task.wait(0.4)
        pcall(function()
        local log = _G.__ISS_ANIMLOG
        for _, p in ipairs(Players:GetPlayers()) do
            local c = p.Character
            local hum = c and c:FindFirstChildOfClass("Humanoid")
            if hum then
                local ok, tracks = pcall(hum.GetPlayingAnimationTracks, hum)
                if ok then
                    for _, tr in ipairs(tracks) do
                        local animI = tr.Animation
                        local id = animI and tostring(animI.AnimationId) or "?"
                        if id ~= "?" and not animSeen[id] then
                            animSeen[id] = true
                            local nm = animI and animI.Name or "?"
                            if #log >= 50 then table.remove(log, 1) end
                            local stamp = os.date("%H:%M:%S")
                            table.insert(log, stamp .. " " .. p.Name .. " animName=" .. nm .. " id=" .. id)
                        end
                    end
                end
            end
        end
        end)
    end
end)
