--==============================================================
local function nearestOppDist()
    local root = getRoot(getChar())
    if not root then return math.huge end
    local best = math.huge
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= LocalPlayer then
            local r = p.Character and p.Character:FindFirstChild("HumanoidRootPart")
            if r then
                local d = (r.Position - root.Position).Magnitude
                if d < best then best = d end
            end
        end
    end
    return best
end
-- does any opponent look like they are about to tackle / kick us?
local function nearestThreat()
    local root = getRoot(getChar())
    if not root then return nil end
    local best, bestReason = nil, nil
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= LocalPlayer then
            local c = p.Character
            local r = c and c:FindFirstChild("HumanoidRootPart")
            if r then
                local v = r.AssemblyLinearVelocity or Vector3.new()
                local flat = Vector3.new(v.X, 0, v.Z)
                local speed = flat.Magnitude
                local toUs = root.Position - r.Position
                local dist = toUs.Magnitude
                if dist < 24 then
                    local threat, reason
                    if dist < 8 then
                        threat, reason = true, "in-contact"
                    else
                        local closing = (dist > 0.1) and (toUs:Dot(flat) / dist) or 0
                        if speed > 22 and closing > 0.2 then
                            threat, reason = true, "fast-closing"
                        end
                    end
                    if threat and (not best or dist < best.dist) then
                        best = { char = c, root = r, dist = dist }
                        bestReason = reason
                    end
                end
            end
        end
    end
    return best, bestReason
end
--==============================================================
-- DRIBBLE ENGINE v2 (mechanic-accurate, learned from Dmc)
-- Opponent attacks arrive as replicated packets on every child of
-- Remotes.Ball: TackleStarted / KickChargeStarted /
-- KickChargeUpdated / KickReleased / KickChargeCanceled.
-- While we carry the ball we rebuild the attacker's live tackle
-- dash / kick charge from those packets, sweep the game's own
