-- guarantee the native dribble APIs the engine drives.
local function drPath(path)
    local obj = ReplicatedStorage
    for frag in string.gmatch(path, "[^.]+") do
        obj = obj and obj:FindFirstChild(frag) or nil
        if not obj then return nil end
    end
    if obj:IsA("ModuleScript") then
        local ok, mod = pcall(require, obj)
        if ok and type(mod) == "table" then return mod end
    end
    return nil
end
local DRN = nil
local function drLoadNative()
    DRN = {
        Dodge = drPath("Client.Gameplay.Actions.Dodge"),
        ShootC = drPath("Client.Gameplay.Actions.Shoot"),
        SprintC = drPath("Client.Gameplay.Player.Sprint"),
        Slide = drPath("Modules.Actions.SlideTackle"),
        Hitbox = drPath("Modules.Gameplay.HitboxSettings"),
        Charge = drPath("Modules.Actions.ActionChargeState"),
        Effects = drPath("Client.Gameplay.Actions.TackleEffects"),
        Motion = drPath("Modules.Characters.CharacterMotion"),
        Actors = drPath("Modules.Characters.Actors"),
        Teams = drPath("Client.Gameplay.ActorTeams"),
        Controls = drPath("Modules.Gameplay.Controls"),
    }
    local dod, con = DRN.Dodge, DRN.Controls
    DRN.ready = dod ~= nil and type(dod.HandleInputBegan) == "function"
        and type(dod.IsDribbling) == "function"
        and type(dod.UpdateControlState) == "function"
        and con ~= nil and type(con.CreateInput) == "function"
        and type(con.IsInput) == "function"
    _G.__ISS_DR = DRStats
    _G.__ISS_DRN = { ready = DRN.ready, dodge = type(DRN.Dodge) == "table" and "ok" or "missing",
        controls = type(DRN.Controls) == "table" and "ok" or "missing" }
    return DRN.ready
end
local function drFlat(v) return Vector3.new(v.X, 0, v.Z) end
local function drFinite(n) return type(n) == "number" and n == n and math.abs(n) < math.huge end
local function drVector(v) return typeof(v) == "Vector3" and drFinite(v.X) and drFinite(v.Y) and drFinite(v.Z) end
local function drDirection(value)
    if typeof(value) == "Ray" then value = value.Direction end
    if typeof(value) ~= "Vector3" then return nil end
    local f = drFlat(value)
    if f.Magnitude > 1e-5 then return f.Unit end
    return nil
end
local function drActor(userId)
    local A = DRN and DRN.Actors or M("Actors")
    if A and type(A.GetByUserId) == "function" then
        local ok, actor = pcall(A.GetByUserId, userId)
        if ok and actor then return actor end
    end
    for _, p in ipairs(Players:GetPlayers()) do
        if p.UserId == userId then return p end
    end
    return nil
end
local function drResolveChar(userId)
    local actor = drActor(userId)
    local ch = actor and actor.Character
    if typeof(ch) == "Instance" and ch.Parent then return ch end
    return nil
end
local function drCharacterTeam(character, actor)
    local T = DRN and DRN.Teams or M("ActorTeams")
    if T and type(T.GetActorTeamName) == "function" then
        local ok, t = pcall(T.GetActorTeamName, actor or character)
        if ok and t then return t end
    end
    return nil
end
local function drOpposingTeam(myTeam)
    local MS = M("MatchSettings")
    if not (MS and type(MS.GetOpposingTeamName) == "function") then return nil end
    local names = MS.Constants and MS.Constants.TeamDisplayNames
    if names and names[myTeam] == nil then return nil end
    local ok, opp = pcall(MS.GetOpposingTeamName, myTeam)
    if ok then return opp end
    return nil
end
local function drMotionContext(ch)
    local CM = DRN and DRN.Motion or M("CharacterMotion")
    if CM and type(CM.GetContext) == "function" then
        local ok, ctx = pcall(CM.GetContext, ch)
        if ok and ctx ~= nil then return ctx end
    end
    return "attr:" .. tostring(ch:GetAttribute("MotionContext"))
end
local function drGetCF(ch, root)
    local CM = DRN and DRN.Motion or M("CharacterMotion")
    if CM and type(CM.GetCFrame) == "function" then
        local ok, cf = pcall(CM.GetCFrame, ch)
        if ok and typeof(cf) == "CFrame" then return cf end
    end
    return root.CFrame
end
local function drGetVel(ch, root)
    local CM = DRN and DRN.Motion or M("CharacterMotion")
    if CM and type(CM.GetVelocity) == "function" then
        local ok, v = pcall(CM.GetVelocity, ch)
        if ok and drVector(v) then return v end
    end
    return root.AssemblyLinearVelocity
end
local function drIsChargingActor(actor)
    local CS = DRN and DRN.Charge or M("ActionChargeState")
    if CS and type(CS.IsCharging) == "function" and actor then
        local ok, v = pcall(CS.IsCharging, actor)
        if ok then return v == true end
    end
    return false
end
local function drMaxCharge(userId, actor)
    local P = M("KickPowerups")
    local KC = M("KickCore")
    local kc = KC and KC.Constants
    if P and type(P.GetChargeConstants) == "function" and kc then
        local ok, cc = pcall(P.GetChargeConstants, actor, kc)
        if ok and cc and drFinite(cc.MaximumChargeSeconds) then return cc.MaximumChargeSeconds end
    end
    if kc and drFinite(kc.MaximumChargeSeconds) then return kc.MaximumChargeSeconds end
    return 0.4
end
local function drTackleConstants()
    local ST = DRN and DRN.Slide or M("SlideTackle")
    local travelBy = ST and type(ST.GetMaximumTravelBetween) == "function" and ST.GetMaximumTravelBetween or nil
    return ST, ST and ST.Constants, travelBy
end
local function drReactionLead()
    local clock = os.clock()
    if clock >= DR.nextPing then
        DR.nextPing = clock + DRK.PingSampleSeconds
        local ok, ping = pcall(LocalPlayer.GetNetworkPing, LocalPlayer)
        DR.lead = ok and drFinite(ping) and ping >= 0 and math.min(ping * 0.5, DRK.MaximumNetworkLead) or 0
    end
    return DR.lead
end
-- project our oriented body volume into the attack box's local axes
local function drEnvelope(box, attackCF, ourCF, ourSize)
    local pad = DRK.Padding
    local right = attackCF:VectorToObjectSpace(ourCF.RightVector) * (ourSize.X * 0.5)
    local up = attackCF:VectorToObjectSpace(ourCF.UpVector) * (ourSize.Y * 0.5)
    local fwd = attackCF:VectorToObjectSpace(ourCF.LookVector) * (ourSize.Z * 0.5)
    return box.Size * 0.5 + Vector3.new(
        math.max(pad, math.abs(right.X) + math.abs(up.X) + math.abs(fwd.X)),
        math.max(pad, math.abs(right.Y) + math.abs(up.Y) + math.abs(fwd.Y)),
        math.max(pad, math.abs(right.Z) + math.abs(up.Z) + math.abs(fwd.Z)))
end
-- swept segment (from a - to b, in position space) vs axis-aligned box
local function drSegmentBox(a, b, half)
    local low, high = 0, 1
    for _, axis in ipairs({ "X", "Y", "Z" }) do
        local origin = a[axis]
        local delta = b[axis] - origin
        local extent = half[axis]
        if math.abs(delta) < 1e-8 then
            if math.abs(origin) > extent then return false end
        else
            local enter, leave = (-extent - origin) / delta, (extent - origin) / delta
            if enter > leave then enter, leave = leave, enter end
            low, high = math.max(low, enter), math.min(high, leave)
            if low > high then return false end
        end
    end
    return true
end
-- tackle dash contact: sweep the real SlideTackle hitbox along the dash
local function drTackleContact(ourCF, ourVel, oppCF, oppVel, age, slideDir, horizon, ourRoot)
    local ST, stC, travelBy = drTackleConstants()
    local HS = M("HitboxSettings")
    local box = HS and HS.SlideTackle
    if not (stC and travelBy and box and typeof(box.Size) == "Vector3") then return nil end
    if not drFinite(stC.HitboxDelaySeconds) or not drFinite(stC.HitboxSeconds) then return nil end
    local first = math.max(0, stC.HitboxDelaySeconds - age)
    local last = math.min(horizon or DRK.Lookahead, stC.HitboxDelaySeconds + stC.HitboxSeconds - age)
    if last < first then return nil end
    local dir = slideDir or drFlat(oppVel)
    if dir.Magnitude < 0.1 then dir = drFlat(oppCF.LookVector) end
    if dir.Magnitude < 1e-5 then return nil end
    dir = dir.Unit
    local facing = CFrame.lookAt(oppCF.Position, oppCF.Position + dir)
    local half = drEnvelope(box, facing, ourCF, ourRoot.Size)
    local function pointAt(t)
        local ok, travel = pcall(travelBy, age, age + t, stC.StartupDashDistance, stC.Distance)
        if not ok or not drFinite(travel) then travel = t * (drFinite(stC.Distance) and stC.Distance or 8) end
        local rootCF = facing + dir * travel
        return (rootCF * box.CFrameOffset):PointToObjectSpace(ourCF.Position + ourVel * t)
    end
    local previous = pointAt(first)
    if drSegmentBox(previous, previous, half) then return first end
    local steps = math.max(1, math.ceil((last - first) / DRK.Step))
    for i = 1, steps do
        local t = first + (last - first) * i / steps
        local current = pointAt(t)
        if drSegmentBox(previous, current, half) then return t end
        previous = current
    end
    return nil
end
-- kick contact: sweep the real Kick hitbox in the received launch aim
local function drKickContact(ourCF, ourVel, oppCF, oppVel, releaseAt, aimDir, horizon, ourRoot)
    local HS = M("HitboxSettings")
    local box = HS and HS.Kick
    if not (box and typeof(box.Size) == "Vector3") then return nil end
    local last = horizon or DRK.KickLookahead
    if last < releaseAt then return nil end
    if typeof(aimDir) == "Vector3" then
        oppCF = CFrame.lookAt(oppCF.Position, oppCF.Position + aimDir)
    end
    local half = drEnvelope(box, oppCF, ourCF, ourRoot.Size)
    local function pointAt(t)
        local rootCF = oppCF + oppVel * t
        return (rootCF * box.CFrameOffset):PointToObjectSpace(ourCF.Position + ourVel * t)
    end
    local previous = pointAt(releaseAt)
    if drSegmentBox(previous, previous, half) then return releaseAt end
    local steps = math.max(1, math.ceil((last - releaseAt) / DRK.Step))
    for i = 1, steps do
        local t = releaseAt + (last - releaseAt) * i / steps
        local current = pointAt(t)
        if drSegmentBox(previous, current, half) then return t end
        previous = current
    end
    return nil
end
-- live kick charge window for one opponent (packet-first, native state check)
local function drKickWindow(other, ctx, userId, actor)
    local now = workspace:GetServerTimeNow()
    local state = DRATT[other]
    local early = state and state.ctx == ctx and state.kick
    local charging = drIsChargingActor(actor)
    local TE = DRN and DRN.Effects or M("TackleEffects")
    local observed, compactFill = nil, false
    if TE and type(TE.GetObservedChargeFill) == "function" and drFinite(userId) then
        local ok, f, c = pcall(TE.GetObservedChargeFill, userId)
        if ok then observed, compactFill = f, (c == true) end
    end
    if early then
        if early.ended or now > early.expires then return nil end
        if charging then early.sawCharging = true
        elseif early.sawCharging and now - (early.at or now) > DRK.ChargeStateGrace then
            return nil
        end
        local maximum = drMaxCharge(userId, actor)
        if maximum <= 0 then return nil end
        observed = math.clamp(math.max(now - early.started, (early.charge or 0) + now - (early.at or now)) / maximum, 0, 1)
        compactFill = false
    elseif not charging then
        return nil
    end
    if not observed or observed <= 0 or observed > 1 or compactFill then return nil end
    local maximum = drMaxCharge(userId, actor)
    if maximum <= 0 then return nil end
    local KC = M("KickCore")
    local kc = KC and KC.Constants
    local minimumRelease = nil
    if KC and type(KC.GetMinimumReleaseDelaySeconds) == "function" and kc then
        local ok, v = pcall(KC.GetMinimumReleaseDelaySeconds, observed * maximum, kc)
        if ok then minimumRelease = v end
    end
    if not drFinite(minimumRelease) then minimumRelease = (1 - observed) * maximum * 0.5 end
    if minimumRelease < 0 or minimumRelease > DRK.KickLookahead then return nil end
    return { first = minimumRelease, fill = observed, dir = early and early.dir or nil }
end
local function drDiscover(ch)
    local seen, list = {}, {}
    local function add(char, actor)
        if not char or char == ch or seen[char] or not char.Parent then return end
        local r = char:FindFirstChild("HumanoidRootPart")
        local hum = char:FindFirstChildOfClass("Humanoid")
        if r and hum and hum.Health > 0 then
            seen[char] = true
            list[#list + 1] = { character = char, actor = actor,
                userId = actor and actor.UserId or nil }
        end
    end
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= LocalPlayer then add(p.Character, p) end
    end
    local folder = workspace:FindFirstChild("Characters")
    if folder then
        for _, node in ipairs(folder:GetChildren()) do
            if node:IsA("Model") then add(node, nil) end
        end
    end
    for ch2 in pairs(DRATT) do
        if ch2.Parent then add(ch2, nil) end
    end
    DR.candidates = list
    DR.nextDiscovery = os.clock() + DRK.DiscoverySeconds
end
-- attack packet listener; attaches once per script run
-- forward decl: the hook closures below attach BEFORE the parser body exists,
-- so drPacket must resolve to this local slot, not the (nil) global
local drPacket
local function drAttachPackets()
    drLoadNative()
    if _G.__DR_PACKET_HOOKS then
        for _, c in ipairs(_G.__DR_PACKET_HOOKS) do pcall(function() c:Disconnect() end) end
    end
    _G.__DR_PACKET_HOOKS = {}
    local branch = ReplicatedStorage:FindFirstChild("Remotes")
    local BallRemotes = branch and branch:FindFirstChild("Ball")
    if not BallRemotes then
        DR.legacyNotice = "Remotes.Ball missing; legacy reactive layer active"
        return
    end
    local Controls = DRN and DRN.Controls
    for _, remote in ipairs(BallRemotes:GetChildren()) do
        if remote.Name ~= "State" and (remote:IsA("RemoteEvent") or remote:IsA("UnreliableRemoteEvent")) then
            table.insert(_G.__DR_PACKET_HOOKS, remote.OnClientEvent:Connect(function(...)
                local ok, err = pcall(drPacket, ...)
                if not ok then DRStats.errors += 1; DRStats.lastPacketErr = tostring(err); DR.legacyNotice = "packet parse: " .. tostring(err) end
            end))
        end
    end
    if Controls and type(Controls.IsInput) == "function" then
        table.insert(_G.__DR_PACKET_HOOKS, UserInputService.InputBegan:Connect(function(input, processed)
            if not State.AutoDribble then return end
            if processed then return end
            for _, nm in ipairs({ "Kick", "Pass", "Lob", "RainbowFlick", "Dribble", "Tackle", "Jump" }) do
                local ok, isI = pcall(Controls.IsInput, nm, input)
                if ok and isI then
                    DR.manualUntil = os.clock() + DRK.ManualGrace
                    break
                end
            end
        end))
    end
end
