    -- and inside the repeat delay cannot dive again
    if kind == "GoalkeeperDiveStarted" then
        local userId = args[2]
        if type(userId) == "number" and userId ~= LocalPlayer.UserId then
            local ch = drResolveChar(userId)
            if ch then
                local nowS = workspace:GetServerTimeNow()
                local started = tonumber(args[9]) or tonumber(args[8])
