                local dDir = drDirection(args[3])
                gkDiveTrack[ch] = {
                    started = started,
                    untilT = started + 0.875, -- SaveWindowSeconds
                    recoverAt = started + 1.875, -- RepeatDelaySeconds
                    dir = dDir,
                    pos0 = r and r.Position or nil, -- exact dive origin
                }
