        -- charges are tracked, not just shots
        local started = tonumber(args[9])
        local charge = tonumber(args[5])
        if not started or started > now then return end
        local ch = drResolveChar(userId)
        if not ch then return end
        local ctx = drMotionContext(ch)
        local actor = drActor(userId)
        local previous = DRATT[ch]
        local prevKick = previous and previous.ctx == ctx and previous.kick
        if prevKick and not prevKick.ended and prevKick.started and started < prevKick.started then return end
        local maxC = drMaxCharge(userId, actor)
        if now - started > maxC + 0.25 then return end
        DRATT[ch] = { ctx = ctx,
            slideStarted = previous and previous.ctx == ctx and previous.slideStarted or nil,
            slideDir = previous and previous.ctx == ctx and previous.slideDir or nil,
            kick = { started = started, charge = charge or 0, at = now,
                dir = drDirection(args[6]) or drDirection(args[17]),
                sawCharging = drIsChargingActor(actor), expires = started + maxC + 0.25 } }
    elseif kind == "KickReleased" or kind == "KickChargeCanceled" then
        local ch = drResolveChar(userId)
        local state = ch and DRATT[ch]
        if state and state.kick and not state.kick.ended then
            state.kick.ended = true
            state.kick.sawCharging = nil
