                if DR.lastDodgeAt then
                    local dt = now - DR.lastDodgeAt
                    if dt > 0.6 then
                        DRK.FireWindow = math.clamp(DRK.FireWindow - 0.04, 0.2, 0.5)
                    elseif dt < 0.08 then
                        DRK.FireWindow = math.clamp(DRK.FireWindow + 0.04, 0.2, 0.5)
                    end
                end
            end
