end
drAttachPackets()
-- one native evaluation tick: gates, mechanic scan, native fire
local function drTick(char, root, hum)
    local Dodge = DRN and DRN.Dodge
    local Controls = DRN and DRN.Controls
    local nativeOK = DRN ~= nil and DRN.ready == true
    local dist = nearestOppDist()
    _G.__ISS_DEBUG.dribbleDist = (dist == math.huge and "none" or string.format("%.1f", dist))
    local hasIt = hasBallDribble()
    _G.__ISS_DEBUG.dribbleBall = hasIt
    local nowC = os.clock()
    if not hasIt then
        _G.__ISS_DEBUG.dribbleStatus = "NO BALL"
        return "idle"
    end
    if not nativeOK then
        DR.legacyNotice = DR.legacyNotice or "native handlers unavailable; legacy reactive layer active"
        local threat, reason = nearestThreat()
        _G.__ISS_DEBUG.dribbleThreat = threat and (tostring(reason) .. "@" .. string.format("%.0f", threat.dist)) or "none"
        if threat and (nowC - drLegacyReact) >= 1.5 then
            local okS = pcall(keypress, 32)
            task.delay(0.09, function() pcall(keyrelease, 32) end)
            if okS then drLegacyReact = nowC end
            if okS then
                _G.__ISS_DEBUG.dribbleFlick = (_G.__ISS_DEBUG.dribbleFlick or 0) + 1
                _G.__ISS_DEBUG.dribbleLast = "space:" .. tostring(reason)
            else
                pcall(function() hum.Jump = true end)
                _G.__ISS_DEBUG.dribbleLast = "jump:" .. tostring(reason)
            end
            return "legacy-fired"
        end
        _G.__ISS_DEBUG.dribbleStatus = "LEGACY"
        return "legacy"
    end
    if nowC < DR.manualUntil then
        _G.__ISS_DEBUG.dribbleStatus = "MANUAL"
        return "grace"
    end
    -- native path: refresh the Dribble control state first (as the game does)
    if not Dodge.IsDribbling() and type(Dodge.UpdateControlState) == "function" then
        pcall(Dodge.UpdateControlState)
    end
    if Dodge.IsDribbling() == true then
        _G.__ISS_DEBUG.dribbleStatus = "DRIBBLING"
        return "active"
    end
    local MS = M("MatchSettings")
    if MS and type(MS.IsGoalkeeperCharacter) == "function" then
        local ok, gk = pcall(MS.IsGoalkeeperCharacter, char)
        if ok and gk then
            _G.__ISS_DEBUG.dribbleStatus = "GK ROLE"
            return "blocked"
        end
    end
    -- AVAILABILITY IS A STAT, NOT A GATE (decompiled Controls + Dodge):
    -- the game's cached Available flag flips false whenever you stand
    -- still (no dash direction), are airborne, or sit in the dodge's
