    -- native HandleInputBegan enforces the REAL checks itself (owner,
    -- repeat delay, landed, dash direction, stamina); only the live
    -- cooldown is honored here.
    local okA, a = pcall(Controls.IsAvailable, "Dribble")
    if okA and a == false then
        DRStats.gates["UNREADY"] = (DRStats.gates["UNREADY"] or 0) + 1
    end
    local okC, c = pcall(Controls.IsOnCooldown, "Dribble")
    if okC and c == true then
        _G.__ISS_DEBUG.dribbleStatus = "COOLDOWN"
        DRStats.gates["COOLDOWN"] = (DRStats.gates["COOLDOWN"] or 0) + 1
        return "blocked"
    end
    if true then
        -- StaminaCost lives on the server-side Dodge module, not the client
        -- input module; the native handler enforces it itself, this only
        -- prevents wasted attempts
        local coreDodge = M("Dodge")
        local cost = coreDodge and coreDodge.Constants and coreDodge.Constants.StaminaCost
        if drFinite(cost) then
            local Sprint = DRN and DRN.SprintC
            if Sprint and type(Sprint.CanSpendStamina) == "function" then
                local oks, can = pcall(Sprint.CanSpendStamina, cost, true)
                if oks and can == false then
                    _G.__ISS_DEBUG.dribbleStatus = "LOW STAMINA"
                    DRStats.gates["STAMINA"] = (DRStats.gates["STAMINA"] or 0) + 1
                    return "blocked"
                end
            end
        end
    end
    local CC = M("CharacterControllers")
    if CC and type(CC.IsLanded) == "function" then
        local okl, landed = pcall(CC.IsLanded, char, hum)
        if okl and landed == false then
            _G.__ISS_DEBUG.dribbleStatus = "AIRBORNE"
            DRStats.gates["AIRBORNE"] = (DRStats.gates["AIRBORNE"] or 0) + 1
            return "blocked"
        end
    end
    if nowC < DR.retryAt then
        -- ADAPTIVE RETRY: the same attacker recycling back into us inside the
        -- wait window re-fires quicker than the flat backoff, so the dodge
        -- i-frames stay up through a follow-up steal attempt (the native
        -- cooldown gate still guards over-fire)
        local rt = DR.lastThreat
        local rtRoot = typeof(rt) == "Instance" and rt:FindFirstChild("HumanoidRootPart") or nil
        if rtRoot then
            local rtRange = (State.DribbleRange or 18) * 0.7
            if (rtRoot.Position - root.Position).Magnitude < rtRange then
                DR.retryAt = math.min(DR.retryAt, nowC + 0.12)
            else
                DR.lastThreat = nil -- threat cleared: reset to flat backoff
            end
        end
        if nowC < DR.retryAt then
            _G.__ISS_DEBUG.dribbleStatus = "RETRY WAIT"
            return "retry"
        end
    end
    DRStats.scans += 1
    _G.__ISS_DEBUG.dribbleStatus = "WATCHING"
    -- matching teams keeps friendlies out; contacts allowed when teams unknown
    local myTeam = drCharacterTeam(char, LocalPlayer)
    local opposing = myTeam and drOpposingTeam(myTeam) or nil
    local context = drMotionContext(char)
    local ownCF = drGetCF(char, root)
    local ownVel = drGetVel(char, root)
    if not (drVector(ownCF.Position) and drVector(ownVel)) then return "blocked" end
    if nowC >= DR.nextDiscovery then drDiscover(char) end
    local lead = drReactionLead()
    local horizonT, horizonK = DRK.Lookahead + lead, DRK.KickLookahead + lead
    local nowServer = workspace:GetServerTimeNow()
    local ST, stC = drTackleConstants()
    local best = nil
    local nearestSeen, nearestDist = nil, math.huge
    for _, cand in ipairs(DR.candidates) do
        local other = cand.character
        if other.Parent then
            local d0 = 0
            local oRoot = other:FindFirstChild("HumanoidRootPart")
            if oRoot then
                d0 = (oRoot.Position - root.Position).Magnitude
                if d0 < nearestDist then nearestSeen = other; nearestDist = d0 end
