                    if not sliding and not kick and state
                        and state.followUpAt
                        and nowServer - state.followUpAt < 0.4 then
                        sliding = true
                        age = 0 -- full hitbox window sweeps from now
                        slideDir = state.slideDir
                    end
                    if not sliding and not kick then continue end
                    if sliding then DRStats.threats += 1 end
                    if kick then DRStats.contacts += 1 end
                    local otherCF = drGetCF(other, oRoot)
                    local otherVel = drGetVel(other, oRoot)
                    if drVector(otherCF.Position) and drVector(otherVel) then
                        local eta, reason = nil, nil
                        if sliding then
                            local tEta = drTackleContact(ownCF, ownVel, otherCF, otherVel, age, slideDir, horizonT, root)
                            if tEta then eta, reason = tEta, "tackle" end
                        end
                        if kick then
                            local kEta = drKickContact(ownCF, ownVel, otherCF, otherVel, kick.first, kick.dir, horizonK, root)
                            if kEta and (not eta or kEta < eta) then eta, reason = kEta, "kick" end
                        end
                        if eta and (not best or eta < best.eta or (eta == best.eta and d0 < best.dist)) then
                            best = { character = other, eta = eta, dist = d0, reason = reason }
                        end
                    end
            end
        end
    end
    _G.__ISS_DEBUG.dribbleThreat = nearestSeen and string.format("near@%.0f", nearestDist) or "none"
    if not best then return "none" end
