    local recentShot = (os.clock() - (State.lastAimAt or 0)) < 3.5
    if not headedAt and not recentShot then
        _G.__ISS_DEBUG.intercept = "not-at-enemy"
        return
    end
    -- first future spot WE reach before the ball does (damped approx)
    local bestT, bestSpot = nil, nil
    for t = 0.15, 1.4, 0.1 do
        local spot = ballPos + ballVel * t * math.max(0, 1 - 0.18 * t)
        spot = Vector3.new(spot.X, 0, spot.Z)
        local myFlat = Vector3.new(root.Position.X, 0, root.Position.Z)
        local myT = (spot - myFlat).Magnitude / 22
        if myT <= t + 0.05 then
            bestT, bestSpot = t, spot
            break
        end
    end
    if not bestSpot then
        _G.__ISS_DEBUG.intercept = "unreachable"
        return
    end
    local dir = bestSpot - Vector3.new(root.Position.X, 0, root.Position.Z)
    if dir.Magnitude < 1.5 then
        _G.__ISS_DEBUG.intercept = "on-spot"
        return
    end
    dir = dir.Unit
    local cam = workspace.CurrentCamera
    if not cam then return end
    local lookF = cam.CFrame.LookVector
    lookF = Vector3.new(lookF.X, 0, lookF.Z)
    lookF = (lookF.Magnitude > 0.05) and lookF.Unit or Vector3.new(0, 0, -1)
    local rightF = cam.CFrame.RightVector
    rightF = Vector3.new(rightF.X, 0, rightF.Z)
    rightF = (rightF.Magnitude > 0.05) and rightF.Unit or Vector3.new(1, 0, 0)
    local fD, rD = dir:Dot(lookF), dir:Dot(rightF)
    local keys = {}
    if fD > 0.3 then keys[#keys + 1] = 87 elseif fD < -0.3 then keys[#keys + 1] = 83 end
    if rD > 0.3 then keys[#keys + 1] = 68 elseif rD < -0.3 then keys[#keys + 1] = 65 end
    if #keys > 0 then
        for _, kc in ipairs(keys) do pcall(keypress, kc) end
        task.delay(0.12, function()
            for _, kc in ipairs(keys) do pcall(keyrelease, kc) end
        end)
    end
    _G.__ISS_DEBUG.intercept = string.format("chase t=%.1f d=%.0f", bestT, dir.Magnitude)
end
