ƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â bounce-preferred, so
-- the ball bounds ankle-high under their airborne dive. And a keeper
-- who FUMBLES our net-bound shot (ball loose near the mouth, back in
-- our reach, not in their hands) triggers a FULL auto shot (press,
-- fill, release) at the engine's plain best lane.
--==============================================================
task.spawn(function()
    local pressedAt, releaseFired = nil, false
    local lastAutoShot = 0
    local gkCache, gkCacheAt = nil, 0
    local function findKeeperChar(goal)
        local nowC = os.clock()
        if gkCache and gkCache.Parent and nowC - gkCacheAt < 1.0 then return gkCache end
        local MS = M("MatchSettings")
        local best, bestDist = nil, 34
        for _, pr in ipairs(Players:GetPlayers()) do
            if pr ~= LocalPlayer then
                local c = pr.Character
                local r = c and c:FindFirstChild("HumanoidRootPart")
                if r then
                    local isGK = false
                    if MS then pcall(function() isGK = MS.IsGoalkeeperCharacter(c) end) end
                    local d = (r.Position - goal.Position).Magnitude
                    if isGK and d < bestDist then bestDist = d; best = c end
                end
            end
        end
        if not best then
            -- practice bots: nearest humanized model by the goal
            for _, m in ipairs(workspace:GetDescendants()) do
                if m:IsA("Model") and m ~= LocalPlayer.Character and m:FindFirstChildOfClass("Humanoid") then
                    local r = m:FindFirstChild("HumanoidRootPart")
                    if r then
                        local d = (r.Position - goal.Position).Magnitude
                        if d < bestDist then bestDist = d; best = m end
                    end
                end
            end
        end
        gkCache, gkCacheAt = best, nowC
        return best
    end
    local function releaseHeldCharge()
        if type(mouse1release) ~= "function" then return false end
        return pcall(mouse1release)
    end
    local function autoFullShot()
        if type(mouse1press) ~= "function" or type(mouse1release) ~= "function" then return false end
        task.spawn(function()
            if pcall(mouse1press) then
                task.wait(0.46) -- fill past the 0.40s full-charge
                pcall(mouse1release)
                State.ForceBounceUntil = os.clock() + 0.75 -- fumble shot: prefer the bound finisher
            end
        end)
        return true
    end
    while State.Alive do
        task.wait(0.06)
        if not State.SmartRelease then
            pressedAt, releaseFired = nil, false
            _G.__ISS_DEBUG.smartRelease = "off"
        else
            local okTick, tickErr = pcall(function()
                local nowC = os.clock()
                local UIS = game:GetService("UserInputService")
                local charging = false
                pcall(function() charging = UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) end)
                local sim = type(mouse1release) == "function"
                _G.__ISS_DEBUG.smartRelease = sim and "armed" or "no-mouse-sim"
                if charging and not pressedAt then
                    pressedAt = nowC
                    releaseFired = false
                elseif not charging and pressedAt then
                    pressedAt = nil
                    releaseFired = false
                end
                local goal = getOpponentGoal()
                -- WATCH 1: user's held charge + the keeper jumping -> release now
                if goal and sim and charging and pressedAt and not releaseFired
                    and (nowC - pressedAt) >= 0.12 and hasBall() then
                    local root = getRoot(getChar())
                    local dist = root and (root.Position - goal.Position).Magnitude
                    if dist and dist <= 70 then
                        local keeper = findKeeperChar(goal)
                        local kr = keeper and keeper:FindFirstChild("HumanoidRootPart")
                        local hum = keeper and keeper:FindFirstChildOfClass("Humanoid")
                        local st
                        if hum then pcall(function() st = hum:GetState() end) end
                        local jumped = (st == Enum.HumanoidStateType.Jumping)
                            or (st == Enum.HumanoidStateType.Freefall)
