                        -- vs an auto keeper (Dive -> miss -> helpless) this
                        -- is the free-goal trigger
                        local dived = false
                        if keeper then
                            local dt2 = gkDiveTrack[keeper]
                            if dt2 then
                                dived = workspace:GetServerTimeNow() < (dt2.recoverAt or 0)
                            end
                        end
                        if jumped or dived then
                            releaseFired = true -- one release per held charge
                            if releaseHeldCharge() then
                                State.ForceBounceUntil = nowC + 0.75
                                _G.__ISS_DEBUG.smartReleaseCount =
                                    (_G.__ISS_DEBUG.smartReleaseCount or 0) + 1
                                _G.__ISS_DEBUG.smartRelease = "jump->released"
                            end
                        end
                    end
                end
                -- WATCH 2: fumbled keeper -> comeback ball in reach -> auto shot
                local lastAim = State.lastAimAt or 0
                if goal and sim and nowC - lastAim >= 0.6 and nowC - lastAim <= 4.0
                    and nowC - lastAutoShot >= 3.0 then
                    local root = getRoot(getChar())
                    local ball = getBallPosition()
                    local vel = getBallVelocity()
                    if root and ball and vel.Magnitude < 25 then
                        local bGoal = (ball - goal.Position).Magnitude
                        local bUs = (ball - root.Position).Magnitude
                        local keeper = findKeeperChar(goal)
                        local kr = keeper and keeper:FindFirstChild("HumanoidRootPart")
                        local inHands = kr ~= nil and (ball - kr.Position).Magnitude < 3.5
                        local reachable = hasBall() or bUs < 8
                        if bGoal <= 30 and bUs <= 20 and reachable and not inHands then
                            if autoFullShot() then
                                lastAutoShot = nowC
                                _G.__ISS_DEBUG.smartReleaseCount =
                                    (_G.__ISS_DEBUG.smartReleaseCount or 0) + 1
                                _G.__ISS_DEBUG.smartRelease = "fumble->auto-shot"
                            end
                        end
                    end
                end
            end)
            if not okTick then
                DRStats.errors += 1
                DRStats.lastLoopErr = tostring(tickErr)
                _G.__ISS_DEBUG.smartRelease = "err:" .. tostring(tickErr):sub(1, 48)
            end
        end
    end
end)
--==============================================================
-- SMART SHOT AIM (Silent Aim on volleys/flicks)
--==============================================================
local function cmdKeys(cmd)
    if type(cmd) ~= "table" then return "not-table" end
    local parts = {}
    for k, v in pairs(cmd) do
        local t = type(v)
        if t == "string" then
            table.insert(parts, tostring(k) .. "=" .. v)
        else
            table.insert(parts, tostring(k) .. ":" .. t)
        end
    end
    table.sort(parts)
    return table.concat(parts, ";")
end
local function isVolley(cmd)
    if type(cmd) ~= "table" then return false end
    if cmd.Mode == "Volley" then return true end
    if cmd.IsBicycleKick == true then return true end
    if cmd.IsHeadbutt == true then return true end
    if cmd.Kind == "Volley" then return true end
    return false
end
