    -- bait, no redirect (targeted ones are volleyed passes: leave them)
    if isVolley(cmd) and cmd.TargetUserId == nil then return true end
    if cmd.PassType == "Shot" then return true end
    if cmd.Kind == "Kick" and (cmd.PassType == nil or cmd.PassType == "Shot") then
        if cmd.TargetUserId == nil and cmd.PassType ~= "AssistedPass" and cmd.PassType ~= "Throw" then
            return true
        end
    end
    return false
end
