            -- believable "not shooting" read there is
            local nearPos, nearD = nil, 30
            for _, pl in ipairs(Players:GetPlayers()) do
                if pl ~= LocalPlayer then
                    local pc = pl.Character
                    local pr = pc and pc:FindFirstChild("HumanoidRootPart")
                    if pr then
                        local d = (pr.Position - launchPos).Magnitude
                        if d < nearD then
                            nearD = d
                            nearPos = pr.Position
                        end
                    end
                end
            end
            if nearPos then
                return nearPos + Vector3.new(0, 0.6, 0)
            end
            -- no one near: a field look
            local dirToGoal = Vector3.new(
                goal.Position.X - launchPos.X, 0, goal.Position.Z - launchPos.Z)
            dirToGoal = (dirToGoal.Magnitude > 0.5) and dirToGoal.Unit or Vector3.new(0, 0, -1)
            return launchPos + dirToGoal * 32 + Vector3.new(0, 1.2, 0)
        end
