                -- instant snaps between fake segments read as robotic to
                -- ranked players; a real scan glides (~75ms time constant,
                -- human-speed for every mode including Master Bait)
                local tcG = 0.075
                local gAt = _G.__ISS_BAIT_GLIDE_AT or 0
                local prevG = _G.__ISS_BAIT_GLIDE
                if prevG and nowC - gAt < 0.3 and nowC > gAt then
                    local aG = 1 - math.exp(-(nowC - gAt) / tcG)
                    baitPos = prevG:Lerp(baitPos, math.clamp(aG, 0.1, 0.7))
                end
                _G.__ISS_BAIT_GLIDE = baitPos
                _G.__ISS_BAIT_GLIDE_AT = nowC
                local baitDir = Vector3.new(
                    baitPos.X - launchPos.X, baitPos.Y - launchPos.Y, baitPos.Z - launchPos.Z)
                local flatBait = Vector3.new(baitPos.X - launchPos.X, 0, baitPos.Z - launchPos.Z)
                flatBait = (flatBait.Magnitude < 0.1) and Vector3.new(0, 0, -1) or flatBait.Unit
                baitDir = (baitDir.Magnitude < 0.05) and flatBait or baitDir.Unit
                _G.__ISS_BAIT_FAKE_DIR = baitDir -- publish: the white-line hook bends the preview to the fake
