                -- table write was type-discarded, so the enemy's line kept
                -- the real aim the whole charge
                cmd.AimDirection = baitDir
                cmd.KickDirection = flatBait
                cmd.TargetPosition = nil
                cmd.TargetUserId = nil
                _G.__ISS_DEBUG.lastBail = "BAIT aim"
                _G.__ISS_DEBUG.baitAim = string.format("%.1f,%.1f,%.1f", baitPos.X, baitPos.Y, baitPos.Z)
                return cmd
                end
                _G.__ISS_BAIT_FAKE_DIR = nil -- not charging: the line shows the real aim
                -- not charging: fall through to the real-aim redirect below
            end
            -- INSTANT GOAL TP: teleport ball forward fast while charging,
            -- making every shot/volley fly faster than normal kick
            if State.InstantGoal and phase == "aim" then
                local char = getChar()
                local root = getRoot(char)
                if char and root then
                    local ballPos = getBallPosition()
                    local ball = nil
                    if ballPos then
                        local okB, foundBall = pcall(function()
                            for _, obj in ipairs(workspace:GetDescendants()) do
                                if obj:IsA("BasePart") then
                                    local d = (obj.Position - ballPos).Magnitude
                                    if d < 10 then
                                        return obj
                                    end
                                end
                            end
                        end)
                        if okB then ball = foundBall end
                    end
                    if ball then
                        local goal = getOpponentGoal()
                        local dir
                        if goal then
                            local gPos = goal.Position
                            local toGoal = Vector3.new(gPos.X - ballPos.X, 0, gPos.Z - ballPos.Z)
                            dir = toGoal.Magnitude > 0.1 and toGoal.Unit or root.CFrame.LookVector
                        else
                            local hum = getHum(char)
                            local humDir = hum and root.CFrame.LookVector or Vector3.new(0,0,-1)
                            dir = humDir
                        end
                        local tpPos = ballPos + dir * 30
                        local okT, errT = pcall(function()
                            ball.CFrame = CFrame.new(tpPos)
                            local bv = ball:FindFirstChildOfClass("BodyVelocity") or Instance.new("BodyVelocity")
                            bv.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
                            bv.Velocity = dir * 150
                            bv.Parent = ball
                            task.delay(0.12, function()
                                pcall(function() bv:Destroy() end)
                            end)
                        end)
                        if okT then
                            _G.__ISS_DEBUG.lastBail = "INSTANT GOAL TP"
                        end
                    end
                end
