Â¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â the spin (which survives the
                -- ground contact) carries the bound AWAY from them; no
                -- pre-shift, the drift IS the trick
                if keeperAir and gkInfo and gkInfo.pos and gkInfo.vel
                    and gkInfo.vel.Magnitude > 12 then
                    local h = Vector3.new(
                        goal.Position.X - launchPos.X, 0, goal.Position.Z - launchPos.Z)
                    h = (h.Magnitude > 0.5) and h.Unit or Vector3.new(0, 0, -1)
                    local rightH = Vector3.new(-h.Z, 0, h.X)
                    local side = (gkInfo.pos - launchPos):Dot(rightH)
                    local away = (side > 0) and 1 or -1
                    wantCurve = away * math.clamp(gkInfo.vel.Magnitude / 23, 0.35, 0.7)
                    if (State.BounceMode or "Smart") == "Pressure" then
                        -- GREEN-ARROW DECOY on the anti-dive path: the
                        -- deterministic opposite-half mapping rules here too
                        local flatOutH = Vector3.new(launchPos.X - goal.Position.X, 0, launchPos.Z - goal.Position.Z)
                        local sgn = (away > 0) and 1 or -1 -- dive-away base
                        if flatOutH.Magnitude > 0.5 then
                            local latHatH = flatOutH.Unit:Cross(Vector3.new(0, 1, 0))
                            local latCk = Vector3.new(cornerPos.X - goal.Position.X, 0, cornerPos.Z - goal.Position.Z):Dot(latHatH)
                            sgn = (latCk >= 0) and 1 or -1
                            if State.SnakeInvert == true then sgn = -sgn end
                        end
                        wantCurve = sgn * math.max(math.abs(wantCurve), 0.9)
                    end
                elseif math.abs(uc) < 0.08 then
                    wantCurve = 0 -- the demand model says no curl is needed
                else
                    local spinYaw = estimateSpinY(uc, root) * 0.03 -- rad/s, + = yaw left
                    local nearFace = goal.Position + goal.CFrame.LookVector * (goal.Size.Z * 0.5)
                    if (launchPos - nearFace).Magnitude
                        > (launchPos - (goal.Position - goal.CFrame.LookVector * (goal.Size.Z * 0.5))).Magnitude then
                        nearFace = goal.Position - goal.CFrame.LookVector * (goal.Size.Z * 0.5)
                    end
                    local nFace = Vector3.new(nearFace.X - goal.Position.X, 0, nearFace.Z - goal.Position.Z)
                    nFace = (nFace.Magnitude > 0.05) and nFace.Unit or nil
                    local runDist = nFace and math.abs((nearFace - cornerPos):Dot(nFace)) or nil
                    if not (math.abs(spinYaw) > 0.02) or not runDist then
                        wantCurve = uc -- nothing to fold: ride the plain curl
                    else
                        -- total turn through the crossing: bow of the arc
                        -- from the chord (first/second-order equivalent to
                        -- summarizing both phases' curvature)
                        local t1 = math.max(drFlightTime((cornerPos - launchPos).Magnitude), 0.05)
                        local t2 = math.max(runDist / LAUNCH_SPEED_EST, 0.02)
                        local theta = math.abs(spinYaw) * (t1 + t2)
                        local bow = (LAUNCH_SPEED_EST / math.abs(spinYaw)) * (1 - math.cos(theta))
                        if bow <= 0.3 then
                            wantCurve = uc -- light curl: no pre-shift needed
                        else
                            local flatOut = Vector3.new(
                                launchPos.X - goal.Position.X, 0, launchPos.Z - goal.Position.Z)
                            local latHatOK = flatOut.Magnitude > 0.1
                            if latHatOK then
                                local latHat = flatOut.Unit:Cross(Vector3.new(0, 1, 0))
                                -- the straight-branch convention: aim shifts
                                -- along -latHat by corr. Positive curve input
                                -- yaws the flight LEFT of travel (= -latHat for
                                -- an outward flatOut), bowK = model drift per
                                -- unit input; latKB carries the server's truth
                                local bowK = bow / math.abs(uc)
                                local corrB = math.clamp(
                                    uc * ((SR_CALIB.latKB or 0) - bowK), -3.5, 3.5)
                                if math.abs(corrB) > 0.05 then
                                    local origHop = cornerPos
                                    local shifted = cornerPos - latHat * corrB
                                    local inheritFlat = root and root.AssemblyLinearVelocity or Vector3.new()
                                    -- revalidate BOTH legs of the shifted chain
                                    -- (drop + post-bound run) before committing
                                    if not drLanePathBlocked(launchPos, shifted, inheritFlat)
                                        and not drLaneBlocked(shifted, origHop) then
                                        cornerPos = shifted
                                        -- the intended slot lies ON the goal
                                        -- plane: from the touch the plane is
                                        -- runDist along -nFace (toward the
                                        -- goal); a +nFace offset plants the
                                        -- ref 2*runDist back in the field
                                        -- and poisons latKB with a constant
                                        crossRef = Vector3.new(
                                            origHop.X - nFace.X * runDist, goal.Position.Y,
                                            origHop.Z - nFace.Z * runDist)
                                        _G.__ISS_DEBUG.lastCurveBounce = string.format(
                                            "banana: bow=%.1f corr=%+.2f latKB=%.2f t=%.2fs spin=%.1f",
                                            bow, corrB, SR_CALIB.latKB or 0, t1 + t2, spinYaw / 0.03)
                                    else
                                        wantCurve = 0 -- shifted hop hits a wall: plain bound
                                        _G.__ISS_DEBUG.lastCurveBounce = "banana blocked: straight bound"
                                    end
                                else
                                    wantCurve = uc
                                end
                            else
                                wantCurve = uc
                            end
                        end
                    end
                end
            end
            -- SELF-CALIBRATING LATERAL (the curve-miss fix): the flight
