            -- regardless of how the server actually attaches the bend.
            if not cornerBounce then
                local flatOut = Vector3.new(launchPos.X - goal.Position.X, 0, launchPos.Z - goal.Position.Z)
                if flatOut.Magnitude > 0.1 and not cornerBounce then
                    local planeLatHat = flatOut.Unit:Cross(Vector3.new(0, 1, 0))
                    local corr
                    if (cornerPos - launchPos).Magnitude > (State.LongRange or 40) then
                        corr = (SR_CALIB.latKArc or 0) * wantCurve
                    else
                        corr = (SR_CALIB.latBase or 0) + (SR_CALIB.latKStr or 0) * wantCurve
                    end
                    corr = math.clamp(corr, -6, 6)
                    if math.abs(corr) > 0.05 then
                        cornerPos = cornerPos - planeLatHat * corr
                        _G.__ISS_DEBUG.lastLatShift = string.format(
                            "%+.2f studs (base %+.2f kStr %+.2f kArc %+.2f)",
                            corr, SR_CALIB.latBase or 0, SR_CALIB.latKStr or 0, SR_CALIB.latKArc or 0)
                        -- the shift can push the target outside the mouth-safe
                        -- box: re-pin the lateral (the vertical is untouched)
                        local latLimit = math.max(goal.Size.X * 0.5 - 3.0, 0)
                        local latS = (cornerPos - goal.Position):Dot(goal.CFrame.RightVector)
                        if math.abs(latS) > latLimit then
                            cornerPos = Vector3.new(
                                goal.Position.X + goal.CFrame.RightVector.X * (math.sign(latS) * latLimit),
                                cornerPos.Y,
                                goal.Position.Z + goal.CFrame.RightVector.Z * (math.sign(latS) * latLimit))
                            _G.__ISS_DEBUG.driftClamp = (_G.__ISS_DEBUG.driftClamp or 0) + 1
                        end
                    end
                end
            end
