                local dFlat = fh.Magnitude
                if dFlat > 0.1 then flatDir = fh.Unit end
                flatDir = drCounterSteer(flatDir, math.max(dFlat, 1), root)
                local m3 = math.sqrt(dFlat * dFlat + dy * dy)
                if m3 < 0.5 then m3 = 0.5 end
                dir3D = Vector3.new(flatDir.X * dFlat, dy, flatDir.Z * dFlat) / m3
            end
