            local sync = {}
            for k, v in pairs(m) do
                if type(v) == "table" then
                    local c2 = {}
                    for k2, v2 in pairs(v) do c2[k2] = v2 end
                    sync[k] = c2
                else
                    sync[k] = v
                end
