    local function hookBody(st, ...)
        -- only assist while the player is actually charging a kick,
        -- otherwise just holding the ball hijacks the camera everywhere
        local root = getRoot(getChar())
        if not root then return nil end
        local goal = (st.UseFOVGoal ~= false) and getGoalByFOV() or getOpponentGoal()
        if not goal then return nil end
        local R = M("Renderer")
        local ballPos = nil
        if R and R.GetPosition then pcall(function() ballPos = R.GetPosition() end) end
