        -- the cached target between (shot-time picks always
        -- compute fresh)
        local nowC = os.clock()
        local cache = _G.__ISS_RETICLE_CACHE
        local cornerPos, cornerName
        if cache and nowC - cache.at < 0.12 and cache.goal == goal
            and typeof(cache.pos) == "Vector3" then
            cornerPos, cornerName = cache.pos, cache.name
        else
            local goalieInfo = getGoalieInfo(goal)
            cornerPos, cornerName = computeScorableCorner(goal, goalieInfo)
            _G.__ISS_RETICLE_CACHE = { at = nowC, goal = goal, pos = cornerPos, name = cornerName }
        end
