Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â integrates the game's
-- flight model (gravity + air damping 0.5/s) until the ball crosses the
-- goal plane; far more accurate than the old linear shot at range
local function predictBallCrossing(goal, ballPos, ballVel)
    local n = goal.CFrame.LookVector
    local pos, vel = ballPos, ballVel
    local t, dt = 0, 0.025
    local prevPos = pos
    local prevD = (pos - goal.Position):Dot(n)
    if prevD < -1 then return nil end -- already behind the line
    for _ = 1, 90 do
        vel = vel * math.exp(-0.5 * dt) - Vector3.new(0, workspace.Gravity * dt, 0)
        prevPos = pos
        pos = pos + vel * dt
        t = t + dt
        local d = (pos - goal.Position):Dot(n)
        if d <= 0 and vel:Dot(n) < 0 then
            local f = math.clamp(prevD / math.max(prevD - d, 1e-6), 0, 1)
            local cross = prevPos:Lerp(pos, f)
            local right = goal.CFrame.RightVector
            local halfW = goal.Size.X * 0.5 - 1.0
            local lateral = math.clamp((cross - goal.Position):Dot(right), -halfW, halfW)
            cross = goal.Position + right * lateral + n * 0.5
            return cross, t
        end
        if t > 2.5 or pos.Y < 0 then return nil end
        prevD = d
    end
    return nil
end
-- THE DIVE TRIGGER: the game's own ASSISTED dive (the DiveAssist steers
-- the dive onto the ball) fired via its keybind, with the movement keys
-- synthesized toward the crossing so the dive's dash aims there
local DIVE_VK = { Space = 32, Return = 13, Tab = 9, LeftShift = 160,
    RightShift = 161, LeftControl = 162, E = 69, Q = 81, F = 70, C = 67,
    R = 82, T = 84, V = 86, X = 88, Z = 90, G = 71, H = 72 }
local function diveKeyVK()
    local Controls = M("Controls")
    if Controls and type(Controls.GetKeyCodes) == "function" then
        local ok, codes = pcall(Controls.GetKeyCodes, "Dive")
        if ok and type(codes) == "table" then
            for _, kc in ipairs(codes) do
                if typeof(kc) == "EnumItem" then
                    if DIVE_VK[kc.Name] then return DIVE_VK[kc.Name] end
                    if #kc.Name == 1 then return string.byte(kc.Name) end
                end
            end
        end
    end
    return 70 -- F fallback
end
local function pressToward(root, targetPos)
    local cam = workspace.CurrentCamera
    if not cam then return nil end
    local lookF = cam.CFrame.LookVector
    lookF = Vector3.new(lookF.X, 0, lookF.Z)
    lookF = (lookF.Magnitude > 0.05) and lookF.Unit or Vector3.new(0, 0, -1)
    local rightF = cam.CFrame.RightVector
    rightF = Vector3.new(rightF.X, 0, rightF.Z)
    rightF = (rightF.Magnitude > 0.05) and rightF.Unit or Vector3.new(1, 0, 0)
    local to = targetPos - root.Position
    to = Vector3.new(to.X, 0, to.Z)
    to = (to.Magnitude > 0.1) and to.Unit or lookF
    local fD, rD = to:Dot(lookF), to:Dot(rightF)
    local keys = {}
    if fD > 0.3 then keys[#keys + 1] = 87 elseif fD < -0.3 then keys[#keys + 1] = 83 end
    if rD > 0.3 then keys[#keys + 1] = 68 elseif rD < -0.3 then keys[#keys + 1] = 65 end
    for _, kc in ipairs(keys) do pcall(keypress, kc) end
    return keys
end
local function releaseKeys(keys)
    for _, kc in ipairs(keys or {}) do pcall(keyrelease, kc) end
end
task.spawn(function()
    local gkDiveAt = 0
    local heldKeys = nil
    while State.Alive do
        task.wait(0.05)
        pcall(function()
        if State.AutoGK and not _G.__ISS_DMC_GK and isGoalkeeper() then
            local char = getChar()
            local root = getRoot(char)
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if root and hum then
                local goal = getOwnGoal()
                local ballPos = getBallPosition()
                if goal and ballPos and root then
                    local ballVel = getBallVelocity()
                    local cross, tC = predictBallCrossing(goal, ballPos, ballVel)
                    local rightV = goal.CFrame.RightVector
                    local mouthHalf = goal.Size.X * 0.5
                    local frameBotG = goal.Position.Y - goal.Size.Y * 0.5
                    if cross then
                        _G.__ISS_DEBUG.gkPredict = string.format("t=%.2f @ %.0f,%.0f,%.0f",
                            tC, cross.X, cross.Y, cross.Z)
                    else
