                    -- crossing (clamped into the mouth), 1.5 studs in front
                    -- of it; no crossing = the ball-goal line at the center
                    local ideal
                    if cross then
                        local latC = math.clamp((cross - goal.Position):Dot(rightV),
                            -mouthHalf + 1, mouthHalf - 1)
                        ideal = goal.Position + rightV * latC
                            + goal.CFrame.LookVector * -1.5
                    else
                        local toBall = ballPos - goal.Position
                        toBall = Vector3.new(toBall.X, 0, toBall.Z)
                        toBall = (toBall.Magnitude > 0.5) and toBall.Unit
                            or Vector3.new(0, 0, -1)
                        ideal = goal.Position + toBall * 2.5
                    end
                    ideal = Vector3.new(ideal.X, root.Position.Y, ideal.Z)
                    hum:MoveTo(ideal)
