                            -- intercept assist (no volley-lock refusal) feeds
                            -- the corrections; the dive ALWAYS runs (the
                            -- assist extends it when computable)
                            gkDiveAt = nowC
                            heldKeys = pressToward(root, cross)
                            task.delay(0.03, function()
                                local hum = char and char:FindFirstChildOfClass("Humanoid")
                                local diveMod = M("GoalkeeperDive")
                                local assistM = M("GoalkeeperDiveAssist")
                                local actCmds = M("ActionCommands")
                                local arp = M("ActionRemoteProtocol")
                                if not (diveMod and assistM and actCmds and arp
                                    and root and hum) then return end
                                pcall(function()
                                    local okA, assist = pcall(assistM.GetBodyAssist,
                                        root, ballVel,
                                        { Position = ballPos, Velocity = ballVel,
                                            GroundY = root.Position.Y })
                                    local basis = CFrame.new(root.Position,
                                        Vector3.new(cross.X, root.Position.Y, cross.Z))
                                    local moveDir = (cross - root.Position) * Vector3.new(1, 0, 1)
                                    local choice = diveMod.GetDirectionChoice(moveDir, basis, nil)
                                    local okRun = diveMod.Run(root, hum, choice, function()
                                        return basis
                                    end, {
                                        Assist = assist,
                                        StartedAt = workspace:GetServerTimeNow(),
                                    })
                                    if not okRun then return end
                                    task.wait(0.05)
                                    local okM, motion = pcall(diveMod.GetMotionSample, root)
                                    if not (okM and type(motion) == "table") then return end
                                    local okW, worldDir = pcall(diveMod.GetWorldDirection, choice, basis, nil)
                                    local name = "F"
                                    for _, nm in ipairs({ "F", "LF", "L", "LB", "RF", "R", "RB", "B" }) do
                                        if diveMod.GetDirectionChoiceByName(nm) == choice then
                                            name = nm
                                            break
                                        end
                                    end
                                    local okC, cmd = pcall(actCmds.GoalkeeperDive, {
                                        AimDirection = okW and worldDir or moveDir,
                                        DirectionName = name,
                                        DiveMotion = motion,
                                        ShotTime = workspace:GetServerTimeNow(),
                                    })
                                    if okC and cmd and type(arp.Send) == "function" then
                                        pcall(function() arp.Send(cmd) end)
                                    end
                                end)
                            end)
                            task.delay(0.45, function()
                                releaseKeys(heldKeys)
                                heldKeys = nil
                            end)
                            _G.__ISS_DEBUG.gkSaves = (_G.__ISS_DEBUG.gkSaves or 0) + 1
                            _G.__ISS_DEBUG.gkSave = "assisted dive @" .. string.format("%.1f", cross.Y)
                        end
                    end
                end
            end
        end
        end)
    end
