-- card. Keys for tabs stay Main/Shoot/GK/Misc so every existing
-- addToggle/addCycle/addSlider call keeps working untouched
--==============================================================
local Gui = Instance.new("ScreenGui")
Gui.Name = "UntitledCheatV2"
Gui.ResetOnSpawn = false
Gui.DisplayOrder = 1000
Gui.Parent = LocalPlayer:WaitForChild("PlayerGui")
_G.__ISS_REFRESH = _G.__ISS_REFRESH or {}   -- key -> visual refresh (configs)
_G.__ISS_CFGKEYS = _G.__ISS_CFGKEYS or {}   -- key -> "b" | "s" | "n"
local Frame = Instance.new("Frame")
Frame.Size = UDim2.new(0, 540, 0, 400)
Frame.Position = UDim2.new(0, 24, 0.5, -200)
Frame.BackgroundColor3 = Color3.fromRGB(13, 13, 17)
Frame.BorderSizePixel = 0
Frame.Active = true -- absorbs stray clicks behind the window
Frame.Parent = Gui
Instance.new("UICorner", Frame).CornerRadius = UDim.new(0, 14)
local stroke = Instance.new("UIStroke")
stroke.Color = Color3.fromRGB(42, 42, 50)
stroke.Thickness = 1
stroke.Transparency = 0.25
stroke.Parent = Frame
-- SIDEBAR -----------------------------------------------------
