Sidebar.Size = UDim2.new(0, 158, 1, 0)
Sidebar.BackgroundColor3 = Color3.fromRGB(17, 17, 22)
Sidebar.BorderSizePixel = 0
Sidebar.Parent = Frame
Instance.new("UICorner", Sidebar).CornerRadius = UDim.new(0, 14)
