closeBtn.BorderSizePixel = 0
closeBtn.AutoButtonColor = false
closeBtn.Parent = CONTENT
Instance.new("UICorner", closeBtn).CornerRadius = UDim.new(0, 6)
local uiOpen = true
local reopenBtn = Instance.new("TextButton")
reopenBtn.Size = UDim2.new(0, 96, 0, 28)
reopenBtn.Position = UDim2.new(1, -6, 0.5, -14)
reopenBtn.AnchorPoint = Vector2.new(1, 0.5)
reopenBtn.BackgroundColor3 = Color3.fromRGB(34, 34, 44)
reopenBtn.TextColor3 = Color3.fromRGB(238, 238, 244)
reopenBtn.Font = Enum.Font.GothamBold
reopenBtn.TextSize = 12
reopenBtn.Text = "Untitled"
reopenBtn.BorderSizePixel = 0
reopenBtn.Visible = false
reopenBtn.Parent = Gui
Instance.new("UICorner", reopenBtn).CornerRadius = UDim.new(1, 0)
local function setUIOpen(open)
    uiOpen = open
    Frame.Visible = open
    reopenBtn.Visible = not open
end
closeBtn.Activated:Connect(function() setUIOpen(false) end)
reopenBtn.Activated:Connect(function() setUIOpen(true) end)
UserInputService.InputBegan:Connect(function(input, processed)
    if processed then return end
    if input.KeyCode == Enum.KeyCode.RightShift then
        setUIOpen(not uiOpen)
    end
end)
