local navButtons = {}
local navRefs = {} -- icon/label refs per tab (Instances can't hold custom props)
local tabSwitchHooks = {} -- per-tab refresh hooks (config list rescans when opened)
local tabFrames = {}
local activeTab = "Main"
local switchTab -- forward declaration: nav callbacks reference it before it's assigned
local function makeScrollTab(name)
    local sf = Instance.new("ScrollingFrame")
    sf.Size = UDim2.new(1, -16, 1, -44)
    sf.Position = UDim2.new(0, 9, 0, 34)
    sf.BackgroundTransparency = 1
    sf.BorderSizePixel = 0
    sf.ScrollBarThickness = 3
    sf.ScrollBarImageColor3 = Color3.fromRGB(70, 70, 84)
    sf.CanvasSize = UDim2.new(0, 0, 0, 0)
    sf.Visible = (name == activeTab)
    sf.Parent = CONTENT
    local layout = Instance.new("UIListLayout")
    layout.Padding = UDim.new(0, 6)
    layout.SortOrder = Enum.SortOrder.LayoutOrder
    layout.Parent = sf
    layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
        sf.CanvasSize = UDim2.new(0, 0, 0, layout.AbsoluteContentSize.Y + 8)
    end)
    return sf
end
for i, nav in ipairs(NAV) do
    local b = Instance.new("TextButton")
    b.Size = UDim2.new(1, -20, 0, 32)
    b.Position = UDim2.new(0, 10, 0, 62 + (i - 1) * 38)
    b.BackgroundColor3 = Color3.fromRGB(17, 17, 22)
    b.AutoButtonColor = false
    b.Text = ""
    b.BorderSizePixel = 0
    b.Parent = Sidebar
    Instance.new("UICorner", b).CornerRadius = UDim.new(0, 8)
    local icon = Instance.new("TextLabel")
    icon.Size = UDim2.new(0, 20, 1, 0)
    icon.Position = UDim2.new(0, 10, 0, 0)
    icon.BackgroundTransparency = 1
    icon.Text = nav.icon
    icon.Font = Enum.Font.Gotham
    icon.TextSize = 13
    icon.Parent = b
    local lbl = Instance.new("TextLabel")
    lbl.Size = UDim2.new(1, -20, 1, 0)
    lbl.Position = UDim2.new(0, 36, 0, 0)
    lbl.BackgroundTransparency = 1
    lbl.Text = nav.label
    lbl.Font = Enum.Font.Gotham
    lbl.TextSize = 12
    lbl.TextXAlignment = Enum.TextXAlignment.Left
    lbl.Parent = b
    navRefs[nav.key] = { icon = icon, lbl = lbl }
    navButtons[nav.key] = b
    tabFrames[nav.key] = makeScrollTab(nav.key)
    b.Activated:Connect(function() switchTab(nav.key) end)
end
local sidebarHint = Instance.new("TextLabel")
sidebarHint.Size = UDim2.new(1, -20, 0, 22)
sidebarHint.Position = UDim2.new(0, 10, 1, -30)
sidebarHint.BackgroundTransparency = 1
sidebarHint.Text = "RightShift: toggle UI"
sidebarHint.TextColor3 = Color3.fromRGB(96, 96, 110)
sidebarHint.Font = Enum.Font.Gotham
sidebarHint.TextSize = 10
sidebarHint.Parent = Sidebar
function switchTab(name)
    activeTab = name
    for tname, sf in pairs(tabFrames) do sf.Visible = (tname == name) end
    contentHead.Text = tabDisplay[name] or name
    for tname, b in pairs(navButtons) do
        local refs = navRefs[tname]
        if refs then
            local on = (tname == name)
            b.BackgroundColor3 = on and Color3.fromRGB(34, 34, 44) or Color3.fromRGB(17, 17, 22)
            refs.lbl.TextColor3 = on and Color3.fromRGB(244, 244, 250) or Color3.fromRGB(126, 126, 140)
            refs.icon.TextColor3 = on and Color3.fromRGB(158, 158, 182) or Color3.fromRGB(88, 88, 104)
        end
    end
    for _, h in pairs(tabSwitchHooks) do pcall(h, name) end
end
switchTab("Main")
-- PHONE SUPPORT ------------------------------------------------
-- small screens: auto-fit window, keep every element scrollable;
-- phone executors also get a lighter default footprint
do
    local touchOnly = UserInputService.TouchEnabled and not UserInputService.MouseEnabled
    _G.__ISS_PHONE = touchOnly
    local vp = (workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize)
        or Vector2.new(1200, 800)
    if touchOnly or vp.X < 700 then
        Frame.AnchorPoint = Vector2.new(0.5, 0.5)
        Frame.Position = UDim2.fromScale(0.5, 0.5)
        Frame.Size = UDim2.new(0.96, 0, 0, math.min(430, math.floor(vp.Y * 0.72)))
        if State.AutoGK == true then
            State.AutoGK = false
            warn("[Untitled Cheat v2] phone layout: Auto GK defaulted OFF (toggle it back on if your phone handles it)")
        end
        -- light mode: heavy visual/movement subsystems default OFF on phones
        State.BallESP = false
        State.BallPath = false
        State.AutoDribble = false
        print("[Untitled Cheat v2] phone light mode: BallESP/BallPath/AutoDribble defaulted OFF (toggle them back on freely)")
        print("[Untitled Cheat v2] phone layout active")
    end
end
local function addToggle(tab, label, key)
    local btn = Instance.new("TextButton")
    btn.Size = UDim2.new(1, -4, 0, 30)
    btn.BackgroundColor3 = Color3.fromRGB(21, 21, 27)
    btn.AutoButtonColor = false
    btn.Text = ""
    btn.BorderSizePixel = 0
    btn.Parent = tabFrames[tab]
    Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 8)
    local lbl = Instance.new("TextLabel")
    lbl.Size = UDim2.new(1, -70, 1, 0)
    lbl.Position = UDim2.new(0, 10, 0, 0)
    lbl.BackgroundTransparency = 1
    lbl.TextColor3 = Color3.fromRGB(232, 232, 238)
    lbl.Font = Enum.Font.Gotham
    lbl.TextSize = 12
    lbl.TextXAlignment = Enum.TextXAlignment.Left
    lbl.Parent = btn
    local pill = Instance.new("Frame")
    pill.Size = UDim2.new(0, 34, 0, 18)
    pill.Position = UDim2.new(1, -44, 0.5, -9)
    pill.BackgroundColor3 = Color3.fromRGB(52, 52, 62)
    pill.BorderSizePixel = 0
    pill.Parent = btn
    Instance.new("UICorner", pill).CornerRadius = UDim.new(1, 0)
    local knob = Instance.new("Frame")
    knob.Size = UDim2.new(0, 12, 0, 12)
    knob.Position = UDim2.new(0, 3, 0.5, -6)
    knob.BackgroundColor3 = Color3.fromRGB(180, 180, 190)
    knob.BorderSizePixel = 0
    knob.Parent = pill
    Instance.new("UICorner", knob).CornerRadius = UDim.new(1, 0)
    local function refresh()
        local on = State[key] == true
        lbl.Text = label
        pill.BackgroundColor3 = on and Color3.fromRGB(46, 170, 110) or Color3.fromRGB(52, 52, 62)
        knob.BackgroundColor3 = on and Color3.fromRGB(240, 248, 244) or Color3.fromRGB(150, 150, 160)
        knob.Position = on and UDim2.new(1, -15, 0.5, -6) or UDim2.new(0, 3, 0.5, -6)
    end
    refresh()
    _G.__ISS_REFRESH[key] = refresh
    _G.__ISS_CFGKEYS[key] = "b"
    btn.Activated:Connect(function()
        State[key] = not State[key]
        refresh()
    end)
end
-- cycles a string State value through a fixed option list (Bait Mode etc.)
local function addCycle(tab, label, key, options)
    local btn = Instance.new("TextButton")
    btn.Size = UDim2.new(1, -4, 0, 30)
    btn.BackgroundColor3 = Color3.fromRGB(21, 21, 27)
    btn.AutoButtonColor = false
    btn.Text = ""
    btn.BorderSizePixel = 0
    btn.Parent = tabFrames[tab]
    Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 8)
    local lbl = Instance.new("TextLabel")
    lbl.Size = UDim2.new(1, -120, 1, 0)
    lbl.Position = UDim2.new(0, 10, 0, 0)
    lbl.BackgroundTransparency = 1
    lbl.TextColor3 = Color3.fromRGB(232, 232, 238)
    lbl.Font = Enum.Font.Gotham
    lbl.TextSize = 12
    lbl.TextXAlignment = Enum.TextXAlignment.Left
    lbl.Parent = btn
    local vlbl = Instance.new("TextLabel")
    vlbl.Size = UDim2.new(0, 100, 1, 0)
    vlbl.Position = UDim2.new(1, -12, 0, 0)
    vlbl.AnchorPoint = Vector2.new(1, 0)
    vlbl.BackgroundTransparency = 1
    vlbl.TextColor3 = Color3.fromRGB(158, 150, 235)
    vlbl.Font = Enum.Font.Gotham
    vlbl.TextSize = 12
    vlbl.TextXAlignment = Enum.TextXAlignment.Right
    vlbl.TextTruncate = Enum.TextTruncate.AtEnd
    vlbl.Parent = btn
    local function refresh()
        lbl.Text = label
        vlbl.Text = tostring(State[key])
    end
    refresh()
    _G.__ISS_REFRESH[key] = refresh
    _G.__ISS_CFGKEYS[key] = "s"
    btn.Activated:Connect(function()
        local idx = 1
        for i, v in ipairs(options) do
            if v == State[key] then idx = i break end
        end
        State[key] = options[(idx % #options) + 1]
        refresh()
    end)
end
local function addSlider(tab, label, key, min, max, step)
    local container = Instance.new("Frame")
    container.Size = UDim2.new(1, -4, 0, 46)
    container.BackgroundColor3 = Color3.fromRGB(21, 21, 27)
    container.BorderSizePixel = 0
    container.Parent = tabFrames[tab]
    Instance.new("UICorner", container).CornerRadius = UDim.new(0, 8)
    local lbl = Instance.new("TextLabel")
    lbl.Size = UDim2.new(1, -80, 0, 18)
    lbl.Position = UDim2.new(0, 10, 0, 2)
    lbl.BackgroundTransparency = 1
    lbl.TextColor3 = Color3.fromRGB(232, 232, 238)
    lbl.Font = Enum.Font.Gotham
    lbl.TextSize = 12
    lbl.TextXAlignment = Enum.TextXAlignment.Left
    lbl.Parent = container
    local vlbl = Instance.new("TextLabel")
    vlbl.Size = UDim2.new(0, 70, 0, 18)
    vlbl.Position = UDim2.new(1, -10, 0, 2)
    vlbl.AnchorPoint = Vector2.new(1, 0)
    vlbl.BackgroundTransparency = 1
    vlbl.TextColor3 = Color3.fromRGB(158, 150, 235)
    vlbl.Font = Enum.Font.Gotham
    vlbl.TextSize = 12
    vlbl.TextXAlignment = Enum.TextXAlignment.Right
    vlbl.Parent = container
    local bar = Instance.new("Frame")
    bar.Size = UDim2.new(1, -20, 0, 4)
    bar.Position = UDim2.new(0, 10, 0, 30)
    bar.BackgroundColor3 = Color3.fromRGB(44, 44, 52)
    bar.BorderSizePixel = 0
    bar.Parent = container
    Instance.new("UICorner", bar).CornerRadius = UDim.new(0, 2)
    local fill = Instance.new("Frame")
    fill.Size = UDim2.new(0, 0, 1, 0)
    fill.BackgroundColor3 = Color3.fromRGB(108, 92, 231)
    fill.BorderSizePixel = 0
    fill.Parent = bar
    Instance.new("UICorner", fill).CornerRadius = UDim.new(0, 2)
    local function refresh()
        lbl.Text = label
        vlbl.Text = tostring(State[key])
        local frac = (State[key] - min) / (max - min)
        frac = math.clamp(frac, 0, 1)
        fill.Size = UDim2.new(frac, 0, 1, 0)
    end
    -- LIVE REGISTRY: lets engine code move a slider's State and see the
    -- bar follow (Auto Bounce writes the three bounce gates per shot)
    _G.__ISS_SLIDERS = _G.__ISS_SLIDERS or {}
    _G.__ISS_SLIDERS[key] = refresh
    _G.__ISS_REFRESH[key] = refresh
    _G.__ISS_CFGKEYS[key] = "n"
    refresh()
    local dragging = false
    local UserInputType = Enum.UserInputType
    local function isTouchType(t)
        return tostring(t):sub(1, 5) == "Touch"
    end
    local function wantDrag(input)
        local t = input.UserInputType
        return t == UserInputType.MouseButton1 or isTouchType(t)
    end
    local function wantMove(input)
        local t = input.UserInputType
        return t == UserInputType.MouseMovement or isTouchType(t)
    end
    bar.InputBegan:Connect(function(input)
        if wantDrag(input) then dragging = true end
    end)
    UserInputService.InputEnded:Connect(function(input)
        if wantDrag(input) then dragging = false end
    end)
    UserInputService.InputChanged:Connect(function(input)
        if dragging and wantMove(input) then
            local rel = (input.Position.X - bar.AbsolutePosition.X) / bar.AbsoluteSize.X
            rel = math.clamp(rel, 0, 1)
            local val = min + rel * (max - min)
            val = math.floor(val / step + 0.5) * step
            State[key] = val
            refresh()
        end
    end)
end
