local cfgRows = {}
local selectedCfg = nil
-- dedicated config folder: no more loose files dumped in the workspace root
local CFG_DIR = "UntitledConfigs"
local function cfgPath(name)
    return CFG_DIR .. "/" .. name .. ".json"
end
local function cfgDirReady()
    if type(isfolder) == "function" and isfolder(CFG_DIR) then return true end
    if type(makefolder) == "function" and pcall(makefolder, CFG_DIR) then return true end
    return type(writefile) == "function" -- some executors create folders on write
end
local function cfgRead(name)
    local okR, txt = pcall(readfile, cfgPath(name))
    if okR and txt and #txt > 0 then return true, txt end
    -- legacy: configs stored before the folder existed (or received the old way)
    return pcall(readfile, "ISScfg_" .. name .. ".json")
end
local function cfgDelete(path)
    if pcall(deletefile, path) then return true end
    if pcall(delfile, path) then return true end
    if type(os) == "table" and type(os.remove) == "function" then
        return pcall(os.remove, path)
    end
    return false
end
local function cfgListNames()
    local out, seen = {}, {}
    local okD, files = pcall(listfiles, CFG_DIR)
    if okD and type(files) == "table" then
        for _, f in ipairs(files) do
            local base = tostring(f):match("[/\\]([^/\\]+)$") or tostring(f)
            if base:sub(-5) == ".json" and #base > 5 then
                local nm = base:sub(1, -6)
                if #nm > 0 and not seen[nm] then
                    seen[nm] = true
                    out[#out + 1] = nm
                end
            end
        end
    end
    -- legacy scan: configs living in the workspace root
    local okR2, legacy = pcall(listfiles, "")
    if okR2 and type(legacy) == "table" then
        for _, f in ipairs(legacy) do
            local base = tostring(f):match("[/\\]([^/\\]+)$") or tostring(f)
            if base:sub(1, 7) == "ISScfg_" then
                local nm = (base:sub(8):gsub("%.json$", ""))
                if #nm > 0 and not seen[nm] then
                    seen[nm] = true
                    out[#out + 1] = nm
                end
            end
        end
    end
    table.sort(out)
    return out
end
local function refreshCfgList()
    for _, r in pairs(cfgRows) do r:Destroy() end
    cfgRows = {}
    for _, nm in ipairs(cfgListNames()) do
        local r = Instance.new("TextButton")
        r.Size = UDim2.new(1, -4, 0, 26)
        r.BackgroundColor3 = (nm == selectedCfg) and Color3.fromRGB(34, 34, 44) or Color3.fromRGB(21, 21, 27)
        r.AutoButtonColor = false
        r.TextColor3 = Color3.fromRGB(220, 220, 228)
        r.Font = Enum.Font.Gotham
        r.TextSize = 12
        r.Text = nm
        r.TextXAlignment = Enum.TextXAlignment.Left
        r.Parent = cfgListSf
        Instance.new("UICorner", r).CornerRadius = UDim.new(0, 6)
        r.Activated:Connect(function()
            selectedCfg = nm
            cfgNameBox.Text = nm
            for nm2, rb in pairs(cfgRows) do
                rb.BackgroundColor3 = (nm2 == nm) and Color3.fromRGB(34, 34, 44) or Color3.fromRGB(21, 21, 27)
            end
        end)
        cfgRows[nm] = r
    end
end
local function cfgSnapshot()
    local snap = {}
    for key, kind in pairs(_G.__ISS_CFGKEYS) do
        local v = State[key]
        if kind == "b" then
            snap[key] = (v == true)
        elseif kind == "n" then
            local num = tonumber(v)
            if num then snap[key] = num end
        elseif kind == "s" then
            if v ~= nil then snap[key] = tostring(v) end
        end
    end
    return snap
end
local function cfgApply(snap)
    local n = 0
    for key, v in pairs(snap) do
        if _G.__ISS_CFGKEYS[key] then
            State[key] = v
            local rf = _G.__ISS_REFRESH[key] or (_G.__ISS_SLIDERS and _G.__ISS_SLIDERS[key])
            if rf then pcall(rf) end
            n = n + 1
        end
    end
    return n
end
saveBtn.Activated:Connect(function()
    local raw = cfgTrim(cfgNameBox.Text)
    if #raw == 0 then cfgStatus.Text = "type a config name first" return end
    local name = raw:gsub("[^%w%-_ ]", "")
    if #name == 0 then cfgStatus.Text = "name has no valid characters" return end
    cfgDirReady()
    local okW = pcall(writefile, cfgPath(name), HS:JSONEncode(cfgSnapshot()))
    if okW then
        selectedCfg = name
        cfgNameBox.Text = name
        refreshCfgList()
        cfgStatus.Text = "saved to UntitledConfigs: " .. name
    else
        cfgStatus.Text = "save failed (no writefile in executor)"
    end
end)
loadBtn.Activated:Connect(function()
    local name = selectedCfg or cfgTrim(cfgNameBox.Text)
    if #name == 0 then cfgStatus.Text = "pick or type a config" return end
    local okR, txt = cfgRead(name)
    if not okR or not txt then cfgStatus.Text = "config not found: " .. name return end
    local okD, data = pcall(function() return HS:JSONDecode(txt) end)
    if not okD or type(data) ~= "table" then cfgStatus.Text = "bad config file" return end
    local n = cfgApply(data)
    cfgStatus.Text = "loaded " .. name .. " (" .. n .. " settings)"
end)
delBtn.Activated:Connect(function()
    local name = selectedCfg or cfgTrim(cfgNameBox.Text)
    if #name == 0 then cfgStatus.Text = "pick a config to delete" return end
    local gone = cfgDelete(cfgPath(name))
    if not gone then gone = cfgDelete("ISScfg_" .. name .. ".json") end
    if gone then
        if selectedCfg == name then selectedCfg = nil end
        cfgNameBox.Text = ""
        refreshCfgList()
        cfgStatus.Text = "deleted: " .. name
    else
        cfgStatus.Text = "delete failed (no deletefile in executor)"
    end
end)
-- shares the selected config as a one-line import snippet (paste to a friend)
local shareRow = Instance.new("Frame")
shareRow.Size = UDim2.new(1, -4, 0, 30)
shareRow.BackgroundTransparency = 1
shareRow.Parent = cfgFrame
local shareBtn = Instance.new("TextButton")
shareBtn.Size = UDim2.new(1, 0, 1, 0)
shareBtn.BackgroundColor3 = Color3.fromRGB(34, 34, 44)
shareBtn.TextColor3 = Color3.fromRGB(238, 238, 244)
shareBtn.Font = Enum.Font.Gotham
shareBtn.TextSize = 12
shareBtn.Text = "Copy config (share with a friend)"
shareBtn.BorderSizePixel = 0
shareBtn.Parent = shareRow
Instance.new("UICorner", shareBtn).CornerRadius = UDim.new(0, 8)
shareBtn.Activated:Connect(function()
    local name = selectedCfg or cfgTrim(cfgNameBox.Text)
    if #name == 0 then cfgStatus.Text = "pick a config to copy" return end
    local okR, txt = cfgRead(name)
    if not okR or not txt then cfgStatus.Text = "config not found: " .. name return end
    -- single-quoted Lua literal; JSON only ever carries double quotes
    local payload = tostring(txt):gsub("\\", "\\\\"):gsub("'", "\\'")
    -- phone-safe: fall back to a root file if the executor can't make folders
    local snippet = 'pcall(function() makefolder("UntitledConfigs") end) '
        .. 'local okW = pcall(writefile, "UntitledConfigs/' .. name .. '.json", \'' .. payload .. '\') '
        .. 'if not okW then writefile("ISScfg_' .. name .. '.json", \'' .. payload .. '\') end'
    local copied = false
    if type(setclipboard) == "function" then copied = pcall(setclipboard, snippet) end
    if not copied and type(toclipboard) == "function" then copied = pcall(toclipboard, snippet) end
    if not copied and type(writeclipboard) == "function" then copied = pcall(writeclipboard, snippet) end
    if copied then
        cfgStatus.Text = "copied - paste it to your friend"
    else
        cfgStatus.Text = "clipboard unavailable - printed to console"
    end
    print("[Untitled Cheat v2] config paste (send this to your friend):")
    print(snippet)
end)
