Instance.new("UICorner", importBtn).CornerRadius = UDim.new(0, 8)
importBtn.Activated:Connect(function()
    local s = cfgTrim(importBox.Text)
    if #s == 0 then cfgStatus.Text = "paste a config first" return end
    -- accept the full share snippet OR raw JSON
    local payload = s:match(",%s*'(.-)'")
    local name = s:match("UntitledConfigs/(.-)%.json") or s:match("ISScfg_(.-)%.json")
    if payload then
        -- inverse of the share-side escaping
        payload = payload:gsub("\\'", "'"):gsub("\\\\", "\\")
    end
    local raw = payload or s
    local okD, data = pcall(function() return HS:JSONDecode(raw) end)
    if not okD or type(data) ~= "table" then
        cfgStatus.Text = "not a config (bad JSON)"
        return
    end
    local n = cfgApply(data)
    if not name or #name == 0 then name = "imported" end
    name = name:gsub("[^%w%-_ ]", "")
    if #name == 0 then name = "imported" end
    cfgDirReady()
    pcall(writefile, cfgPath(name), HS:JSONEncode(data))
    selectedCfg = name
    cfgNameBox.Text = name
    importBox.Text = ""
    refreshCfgList()
    cfgStatus.Text = "imported " .. name .. " (" .. n .. " settings)"
end)
-- rescan the config list every time the Configs tab is opened,
-- so files copied into the workspace mid-session show up
tabSwitchHooks["Config"] = refreshCfgList
-- one-time migration: scoop legacy loose ISScfg_*.json into UntitledConfigs/
pcall(function()
    local ok, legacy = pcall(listfiles, "")
    if ok and type(legacy) == "table" and type(writefile) == "function" then
        cfgDirReady()
        for _, f in ipairs(legacy) do
            local base = tostring(f):match("[/\\]([^/\\]+)$") or tostring(f)
            if base:sub(1, 7) == "ISScfg_" then
                local nm = (base:sub(8):gsub("%.json$", ""))
                if #nm > 0 then
                    local okR, txt = pcall(readfile, "ISScfg_" .. nm .. ".json")
                    if okR and txt and #txt > 0 then
                        pcall(writefile, cfgPath(nm), txt)
                        cfgDelete("ISScfg_" .. nm .. ".json")
                    end
                end
            end
        end
    end
end)
refreshCfgList()
