task.spawn(function()
    while State.Alive do
        task.wait(1)
        pcall(function()
        local d = _G.__ISS_DEBUG
        local t = resolveTeams()
        statusLbl.Text = string.format(
            "ball: %s | aimBail: %s\nrel: %d upd: %d mut: %d updMut: %d\nreticle: %d | corner: %s\ngk: pos=%s ownGoal=%s\npredict: %s\nrelease: %s",
            d.ballOwned, d.lastBail,
            d.releases, d.updates or 0, d.mutates or 0, d.updateMutates or 0,
            d.reticleRedirects, tostring(d.lastCorner),
            d.lastGoaliePos, t and ("own=" .. tostring(t.OwnName)) or "no-team",
            d.gkPredict,
            string.sub(d.lastReleaseKeys or "-", 1, 70)
        )
        end)
    end
end)
-- drag
local dragging, dragStart, startPos
Frame.InputBegan:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
        if input.Position.Y - Frame.AbsolutePosition.Y < 30 then
            dragging = true
            dragStart = input.Position
            startPos = Frame.Position
        end
    end
end)
UserInputService.InputChanged:Connect(function(input)
    if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
        local delta = input.Position - dragStart
        Frame.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
    end
end)
UserInputService.InputEnded:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
        dragging = false
    end
end)
UserInputService.InputBegan:Connect(function(input, gp)
    if gp then return end
    if input.KeyCode == Enum.KeyCode.RightShift then
        State.UIOpen = not State.UIOpen
        Frame.Visible = State.UIOpen
    end
end)
